{"command":"cd /workspace/assets; python3 - <<'EOF'
import zlib
data=open('test_data.orc','rb').read()
ps_len=data[-1]
ps=data[-1-ps_len:-1]
def varint(b,p):
    r=0;sh=0
    while True:
        x=b[p]; p+=1; r|=(x&0x7f)<<sh; sh+=7
        if not x&0x80: return r,p
def parse(b):
    p=0; out=[]
    while p<len(b):
        key,p=varint(b,p); f=key>>3; wt=key&7
        if wt==0: v,p=varint(b,p)
        elif wt==2:
            l,p=varint(b,p); v=b[p:p+l]; p+=l
        elif wt==1: v=b[p:p+8]; p+=8
        elif wt==5: v=b[p:p+4]; p+=4
        out.append((f,wt,v))
    return out
psf=dict((f,v) for f,w,v in parse(ps))
flen=psf[1]; comp=psf[2]
footer_comp=data[-1-ps_len-flen:-1-ps_len]
# decompress ORC chunks
def orc_decompress(buf):
    out=b''; p=0
    while p<len(buf):
        h=buf[p]|(buf[p+1]<<8)|(buf[p+2]<<16); p+=3
        orig=h&1; l=h>>1
        chunk=buf[p:p+l]; p+=l
        if orig: out+=chunk
        else: out+=zlib.decompress(chunk,-15)
    return out
footer=orc_decompress(footer_comp)
f=parse(footer)
for fld in f:
    if fld[0]==4:  # types
        print('type', parse(fld[2]))
    elif fld[0]==3: print('stripe', parse(fld[2]))
    elif fld[0] in (1,2,6,7,8): print(fld[0], fld[2])
    elif fld[0]==5: pass  # metadata
    else: print(fld[0], fld[1])
EOF"}

