cat > src/sqlite.go <<'EOF'
package main

/*
#cgo LDFLAGS: -lsqlite3
#include <sqlite3.h>
#include <stdlib.h>
#include <string.h>

static int bind_text_go(sqlite3_stmt *stmt, int idx, const char *s, int n) {
	return sqlite3_bind_text(stmt, idx, s, n, SQLITE_TRANSIENT);
}
static int bind_blob_go(sqlite3_stmt *stmt, int idx, const void *s, int n) {
	return sqlite3_bind_blob(stmt, idx, s, n, SQLITE_TRANSIENT);
}
*/
import "C"

import (
	"errors"
	"fmt"
	"strings"
	"unsafe"
)

// DB is a thin wrapper over a sqlite3 connection.
type DB struct {
	conn *C.sqlite3
}

// Stmt is a prepared statement.
type Stmt struct {
	db   *DB
	stmt *C.sqlite3_stmt
	tail string
}

func openDB(path string) (*DB, error) {
	cpath := C.CString(path)
	defer C.free(unsafe.Pointer(cpath))
	var conn *C.sqlite3
	rc := C.sqlite3_open_v2(cpath, &conn, C.SQLITE_OPEN_READWRITE|C.SQLITE_OPEN_CREATE|C.SQLITE_OPEN_URI, nil)
	if rc != C.SQLITE_OK {
		msg := "unable to open database"
		if conn != nil {
			msg = C.GoString(C.sqlite3_errmsg(conn))
			C.sqlite3_close_v2(conn)
		}
		return nil, errors.New(msg)
	}
	C.sqlite3_busy_timeout(conn, 5000)
	return &DB{conn: conn}, nil
}

func (db *DB) Close() {
	if db.conn != nil {
		C.sqlite3_close_v2(db.conn)
		db.conn = nil
	}
}

func (db *DB) errmsg() error {
	return errors.New(C.GoString(C.sqlite3_errmsg(db.conn)))
}

// Prepare compiles the first statement in sql, returning the remaining text.
func (db *DB) Prepare(sql string) (*Stmt, error) {
	csql := C.CString(sql)
	defer C.free(unsafe.Pointer(csql))
	var stmt *C.sqlite3_stmt
	var tail *C.char
	rc := C.sqlite3_prepare_v2(db.conn, csql, C.int(len(sql)+1), &stmt, &tail)
	if rc != C.SQLITE_OK {
		return nil, db.errmsg()
	}
	var rest string
	if tail != nil {
		rest = C.GoString(tail)
	}
	return &Stmt{db: db, stmt: stmt, tail: rest}, nil
}

// Exec runs all statements in sql without returning rows.
func (db *DB) Exec(sql string) error {
	csql := C.CString(sql)
	defer C.free(unsafe.Pointer(csql))
	var errmsg *C.char
	rc := C.sqlite3_exec(db.conn, csql, nil, nil, &errmsg)
	if rc != C.SQLITE_OK {
		var msg string
		if errmsg != nil {
			msg = C.GoString(errmsg)
			C.sqlite3_free(unsafe.Pointer(errmsg))
		} else {
			msg = C.GoString(C.sqlite3_errmsg(db.conn))
		}
		return errors.New(msg)
	}
	return nil
}

func (s *Stmt) Empty() bool { return s.stmt == nil }

func (s *Stmt) Finalize() {
	if s.stmt != nil {
		C.sqlite3_finalize(s.stmt)
		s.stmt = nil
	}
}

func (s *Stmt) Reset() {
	if s.stmt != nil {
		C.sqlite3_reset(s.stmt)
		C.sqlite3_clear_bindings(s.stmt)
	}
}

// Bind binds a Go value at the 1-based index.
func (s *Stmt) Bind(idx int, v interface{}) error {
	var rc C.int
	switch x := v.(type) {
	case nil:
		rc = C.sqlite3_bind_null(s.stmt, C.int(idx))
	case int64:
		rc = C.sqlite3_bind_int64(s.stmt, C.int(idx), C.sqlite3_int64(x))
	case int:
