package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"io"
	"sort"
)

// OMap is an insertion-ordered string-keyed map used to represent JSON
// objects while remembering the key order they were seen in.
type OMap struct {
	Keys []string
	Vals map[string]interface{}
}

func NewOMap() *OMap {
	return &OMap{Vals: map[string]interface{}{}}
}

func (m *OMap) Set(k string, v interface{}) {
	if _, ok := m.Vals[k]; !ok {
		m.Keys = append(m.Keys, k)
	}
	m.Vals[k] = v
}

func (m *OMap) Get(k string) (interface{}, bool) {
	v, ok := m.Vals[k]
	return v, ok
}

func (m *OMap) Len() int { return len(m.Keys) }

// SortedKeys returns the keys in byte order.
func (m *OMap) SortedKeys() []string {
	ks := make([]string, len(m.Keys))
	copy(ks, m.Keys)
	sort.Strings(ks)
	return ks
}

// MarshalJSON encodes the map with keys in sorted order, mirroring how a
// plain Go map would be encoded.
func (m *OMap) MarshalJSON() ([]byte, error) {
	var buf bytes.Buffer
	buf.WriteByte('{')
	for i, k := range m.SortedKeys() {
		if i > 0 {
			buf.WriteByte(',')
		}
		kb, err := json.Marshal(k)
		if err != nil {
			return nil, err
		}
		buf.Write(kb)
		buf.WriteByte(':')
		vb, err := json.Marshal(m.Vals[k])
		if err != nil {
			return nil, err
		}
		buf.Write(vb)
	}
	buf.WriteByte('}')
	return buf.Bytes(), nil
}

// decodeJSONValue reads a single JSON value from the decoder, producing
// nil, bool, float64, string, []interface{} or *OMap.
func decodeJSONValue(dec *json.Decoder) (interface{}, error) {
	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}
	return buildFromToken(dec, tok)
}

func buildFromToken(dec *json.Decoder, tok json.Token) (interface{}, error) {
	switch t := tok.(type) {
	case json.Delim:
		switch t {
		case '{':
			m := NewOMap()
			for {
				kt, err := dec.Token()
				if err != nil {
					return nil, err
				}
				if d, ok := kt.(json.Delim); ok && d == '}' {
					return m, nil
				}
				key, ok := kt.(string)
				if !ok {
					return nil, errors.New("invalid object key")
				}
				vt, err := dec.Token()
				if err != nil {
					return nil, err
				}
				v, err := buildFromToken(dec, vt)
				if err != nil {
					return nil, err
				}
				m.Set(key, v)
			}
		case '[':
			arr := []interface{}{}
			for {
				vt, err := dec.Token()
				if err != nil {
					return nil, err
				}
				if d, ok := vt.(json.Delim); ok && d == ']' {
					return arr, nil
				}
				v, err := buildFromToken(dec, vt)
				if err != nil {
					return nil, err
				}
				arr = append(arr, v)
			}
		}
		return nil, errors.New("unexpected delimiter")
	case float64:
		return t, nil
	case string:
		return t, nil
	case bool:
		return t, nil
	case nil:
		return nil, nil
	}
	return nil, errors.New("unexpected token")
}

// parseJSON decodes the first JSON value in r.
func parseJSON(r io.Reader) (interface{}, error) {
	dec := json.NewDecoder(r)
	return decodeJSONValue(dec)
}

// toPlain converts OMaps into regular maps recursively (for encoding
// via encoding/json where ordering is irrelevant).
func toPlain(v interface{}) interface{} {
	switch x := v.(type) {
	case *OMap:
		out := make(map[string]interface{}, len(x.Keys))
		for _, k := range x.Keys {
			out[k] = toPlain(x.Vals[k])
		}
		return out
	case []interface{}:
		out := make([]interface{}, len(x))
		for i, e := range x {
			out[i] = toPlain(e)
		}
		return out
	}
	return v
}
EOF
echo ok"}

