package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"
)

const (
	KindScalar  = "scalar"
	KindArray   = "array"
	KindObject  = "object"
	KindVaried  = "varied"
	KindUnknown = "unknown"

	ScalarNumber  = "number"
	ScalarString  = "string"
	ScalarBoolean = "boolean"
	ScalarNull    = "null"

	shapeSampleSize = 100
)

// Shape describes the inferred structure of a JSON-like value.
type Shape struct {
	Kind   string
	Scalar string
	Array  *Shape
	Object *ObjectShape
	Varied []*Shape
}

// ObjectShape keeps the field shapes in insertion order.
type ObjectShape struct {
	Keys   []string
	Fields map[string]*Shape
}

func newObjectShape() *ObjectShape {
	return &ObjectShape{Fields: map[string]*Shape{}}
}

func (o *ObjectShape) set(k string, s *Shape) {
	if _, ok := o.Fields[k]; !ok {
		o.Keys = append(o.Keys, k)
	}
	o.Fields[k] = s
}

func scalarShape(s string) *Shape { return &Shape{Kind: KindScalar, Scalar: s} }
func unknownShape() *Shape         { return &Shape{Kind: KindUnknown} }
func nullShape() *Shape            { return scalarShape(ScalarNull) }

func shapesEqual(a, b *Shape) bool {
	if a == nil || b == nil {
		return a == b
	}
	if a.Kind != b.Kind {
		return false
	}
	switch a.Kind {
	case KindScalar:
		return a.Scalar == b.Scalar
	case KindUnknown:
		return true
	case KindArray:
		return shapesEqual(a.Array, b.Array)
	case KindObject:
		if len(a.Object.Fields) != len(b.Object.Fields) {
			return false
		}
		for k, av := range a.Object.Fields {
			bv, ok := b.Object.Fields[k]
			if !ok || !shapesEqual(av, bv) {
				return false
			}
		}
		return true
	case KindVaried:
		if len(a.Varied) != len(b.Varied) {
			return false
		}
		for i := range a.Varied {
			if !shapesEqual(a.Varied[i], b.Varied[i]) {
				return false
			}
		}
		return true
	}
	return false
}

// variedLeaves flattens nested varied shapes into their non-varied members.
func variedLeaves(s *Shape) []*Shape {
	if s.Kind != KindVaried {
		return []*Shape{s}
	}
	var out []*Shape
	for _, v := range s.Varied {
		out = append(out, variedLeaves(v)...)
	}
	return out
}

// variedContains reports whether s equals one of the (deep) members of v.
func variedContains(v *Shape, s *Shape) bool {
	for _, leaf := range variedLeaves(v) {
		if shapesEqual(leaf, s) {
			return true
		}
	}
	return false
}

func makeVaried(a, b *Shape) *Shape {
	return &Shape{Kind: KindVaried, Varied: []*Shape{a, b}}
}

// mergeVariedInto folds the members of acc (a varied shape) into into (also
// varied). Members already represented in into are dropped.
func mergeVariedInto(acc, into *Shape) *Shape {
	leaves := variedLeaves(acc)
	contained := 0
	for _, l := range leaves {
		if variedContains(into, l) {
			contained++
		}
	}
	if contained == len(leaves) {
		return into
	}
	if contained == 0 {
		return makeVaried(into, acc)
	}
	result := into
	for i := len(acc.Varied) - 1; i >= 0; i-- {
		e := acc.Varied[i]
		if e.Kind == KindVaried {
			result = mergeVariedInto(e, result)
		} else if !variedContains(result, e) {
			result = makeVaried(result, e)
		}
	}
	return result
}

// mergeShapes combines the accumulated shape with a newly observed one.
func mergeShapes(acc, next *Shape) *Shape {
	if shapesEqual(acc, next) {
		return acc
	}
	if acc.Kind == KindArray && next.Kind == KindArray {
		return mergeShapes(acc.Array, next.Array)
	}
	if acc.Kind == KindObject && next.Kind == KindObject {
		out := newObjectShape()
		for _, k := range acc.Object.Keys {
			av := acc.Object.Fields[k]
			if nv, ok := next.Object.Fields[k]; ok {
				out.set(k, mergeShapes(av, nv))
			} else {
				out.set(k, mergeShapes(av, nullShape()))
			}
		}
		for _, k := range next.Object.Keys {
			if _, ok := acc.Object.Fields[k]; ok {
				continue
			}
			out.set(k, mergeShapes(next.Object.Fields[k], nullShape()))
		}
		return &Shape{Kind: KindObject, Object: out}
	}
	if acc.Kind == KindVaried {
		if next.Kind == KindVaried {
			return mergeVariedInto(acc, next)
		}
		if variedContains(acc, next) {
			return acc
		}
		return makeVaried(acc, next)
	}
	return makeVaried(acc, next)
}

// getShape infers the shape of a decoded JSON value, sampling arrays.
func getShape(v interface{}) *Shape {
	switch x := v.(type) {
	case nil:
		logVerbose("Skipping unknown type: %!s(<nil>)")
		return unknownShape()
	case bool:
		return scalarShape(ScalarBoolean)
	case float64:
		return scalarShape(ScalarNumber)
	case int64:
		return scalarShape(ScalarNumber)
	case int:
		return scalarShape(ScalarNumber)
	case string:
		return scalarShape(ScalarString)
	case []byte:
		return scalarShape(ScalarString)
	case *OMap:
		o := newObjectShape()
		for _, k := range x.Keys {
			o.set(k, getShape(x.Vals[k]))
		}
		return &Shape{Kind: KindObject, Object: o}
	case map[string]interface{}:
		o := newObjectShape()
		for _, k := range sortedMapKeys(x) {
			o.set(k, getShape(x[k]))
		}
		return &Shape{Kind: KindObject, Object: o}
	case []interface{}:
		if len(x) == 0 {
			return &Shape{Kind: KindArray, Array: unknownShape()}
		}
		acc := getShape(x[0])
		n := len(x)
		if n > shapeSampleSize {
			n = shapeSampleSize
		}
		for i := 0; i < n; i++ {
			acc = mergeShapes(acc, getShape(x[i]))
		}
		return &Shape{Kind: KindArray, Array: acc}
	}
	logVerbose("Skipping unknown type: %s", fmt.Sprintf("%v", v))
	return unknownShape()
}

// shapeToJSON renders the shape in the indented schema format.
func shapeToJSON(s *Shape) string {
	var buf bytes.Buffer
	writeShapeJSON(&buf, s, 0)
	return buf.String()
}

func writeShapeJSON(buf *bytes.Buffer, s *Shape, indent int) {
	pad := strings.Repeat("  ", indent)
	inner := strings.Repeat("  ", indent+1)
	buf.WriteString("{\n")
	buf.WriteString(inner + "\"kind\": \"" + s.Kind + "\"")
	switch s.Kind {
	case KindScalar:
		buf.WriteString(",\n" + inner + "\"scalar\": \"" + s.Scalar + "\"")
	case KindArray:
		buf.WriteString(",\n" + inner + "\"array\": ")
		writeShapeJSON(buf, s.Array, indent+1)
	case KindObject:
		buf.WriteString(",\n" + inner + "\"object\": ")
		if len(s.Object.Keys) == 0 {
			buf.WriteString("{}")
		} else {
			buf.WriteString("{\n")
			for i, k := range s.Object.Keys {
				if i > 0 {
					buf.WriteString(",\n")
				}
				kb, _ := json.Marshal(k)
				buf.WriteString(inner + "  " + string(kb) + ": ")
				writeShapeJSON(buf, s.Object.Fields[k], indent+2)
			}
			buf.WriteString("\n" + inner + "}")
		}
	case KindVaried:
		buf.WriteString(",\n" + inner + "\"varied\": ")
		if len(s.Varied) == 0 {
			buf.WriteString("[]")
		} else {
			buf.WriteString("[\n")
			for i, v := range s.Varied {
				if i > 0 {
					buf.WriteString(",\n")
				}
				buf.WriteString(inner + "  ")
				writeShapeJSON(buf, v, indent+2)
			}
			buf.WriteString("\n" + inner + "]")
		}
	}
	buf.WriteString("\n" + pad + "}")
}

// shapeAtPath descends into an object shape along a dotted path.
func shapeAtPath(s *Shape, path string) (*Shape, error) {
	if path == "" {
		return s, nil
	}
	parts := strings.Split(path, ".")
	cur := s
	for _, p := range parts {
		if cur.Kind != KindObject {
			return nil, newUserError("Path enters non-object: " + path)
		}
		next, ok := cur.Object.Fields[p]
		if !ok {
			return nil, newUserError("Path does not exist: " + path)
		}
		cur = next
	}
	return cur, nil
}

// valueAtPath descends into decoded JSON data along a dotted path.
func valueAtPath(v interface{}, path string) (interface{}, bool) {
	if path == "" {
		return v, true
	}
	cur := v
	for _, p := range strings.Split(path, ".") {
		m, ok := cur.(*OMap)
		if !ok {
			return nil, false
		}
		next, ok := m.Get(p)
		if !ok {
			return nil, false
		}
		cur = next
	}
	return cur, true
}

func isArrayOfObjects(s *Shape) bool {
	return s != nil && s.Kind == KindArray && s.Array != nil && s.Array.Kind == KindObject
}
