package main

import (
	"bytes"
	"encoding/json"
	"io"
)

// rowWriter writes a JSON array one element per line in the format
// "[{...},\n{...}]".
type rowWriter struct {
	w     io.Writer
	count int
	err   error
}

func newRowWriter(w io.Writer) *rowWriter {
	rw := &rowWriter{w: w}
	_, rw.err = io.WriteString(w, "[")
	return rw
}

// encodeValue encodes a decoded JSON-like value. Top-level objects keep
// their key order; nested objects are encoded with sorted keys.
func encodeValue(v interface{}) ([]byte, error) {
	switch x := v.(type) {
	case *OMap:
		var buf bytes.Buffer
		buf.WriteByte('{')
		for i, k := range x.Keys {
			if i > 0 {
				buf.WriteByte(',')
			}
			kb, err := json.Marshal(k)
			if err != nil {
				return nil, err
			}
			buf.Write(kb)
			buf.WriteByte(':')
			vb, err := json.Marshal(x.Vals[k])
			if err != nil {
				return nil, err
			}
			buf.Write(vb)
		}
		buf.WriteByte('}')
		return buf.Bytes(), nil
	case map[string]interface{}:
