// csvHeaderName returns the column name for a header cell, substituting
// a spreadsheet-style letter for blank headers.
func csvHeaderName(header []string, i int) string {
	if i < len(header) && header[i] != "" {
		return header[i]
	}
	return columnLetter(i)
}

// convertNumber turns numeric-looking strings into float64 when enabled.
func convertNumber(s string, convert bool) interface{} {
	if !convert {
		return s
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return s
	}
	return f
}

func newCSVReader(r io.Reader, mime string) *csv.Reader {
	cr := csv.NewReader(r)
	cr.FieldsPerRecord = -1
	if mime == MimeTSV {
		cr.Comma = '\t'
	}
	return cr
}

// transformCSV converts a delimited file into the JSON rows format.
func transformCSV(path string, mime string, convertNumbers bool, w io.Writer) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()

	cr := newCSVReader(f, mime)
	rw := newRowWriter(w)
	var header []string
	first := true
	for {
		rec, err := cr.Read()
		if err == io.EOF {
			break
		}
		if err != nil {
			return err
		}
		if first {
			first = false
			header = make([]string, len(rec))
			copy(header, rec)
			continue
		}
		row := NewOMap()
		for i := range rec {
			row.Set(csvHeaderName(header, i), convertNumber(rec[i], convertNumbers))
		}
		for i := len(rec); i < len(header); i++ {
			row.Set(csvHeaderName(header, i), nil)
		}
		if err := rw.Write(row); err != nil {
			return err
		}
	}
	return rw.Close()
}

// importCSVDirect loads a delimited file straight into a SQLite table,
// bypassing the JSON intermediate representation.
func importCSVDirect(db *DB, path string, mime string, table string, convertNumbers bool) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()

	cr := newCSVReader(f, mime)
	var header []string
	var columns []string
	colIndex := map[string]int{}
	var stmt *Stmt
	first := true
	inTx := false
	for {
		rec, err := cr.Read()
		if err == io.EOF {
			break
		}
		if err != nil {
			return err
		}
		if first {
			first = false
			header = make([]string, len(rec))
			copy(header, rec)
			for i := range header {
				name := csvHeaderName(header, i)
				if _, ok := colIndex[name]; !ok {
					colIndex[name] = len(columns)
					columns = append(columns, name)
				}
			}
			continue
		}
		if stmt == nil {
			colType := "TEXT"
			if convertNumbers {
				colType = "NUMERIC"
			}
			create := "CREATE TABLE " + quoteIdent(table) + "("
			insert := "INSERT INTO " + quoteIdent(table) + " VALUES ("
			for i, c := range columns {
				if i > 0 {
					create += ", "
					insert += ", "
				}
				create += quoteIdent(c) + " " + colType
				insert += "?"
			}
			create += ")"
			insert += ")"
			if err := db.Exec(create); err != nil {
				return err
			}
			if err := db.Exec("BEGIN"); err != nil {
				return err
			}
			inTx = true
			stmt, err = db.Prepare(insert)
			if err != nil {
				return err
			}
			defer stmt.Finalize()
		}
		values := make([]interface{}, len(columns))
		for i := range rec {
			if i >= len(header) {
				break
			}
			name := csvHeaderName(header, i)
			values[colIndex[name]] = rec[i]
		}
		stmt.Reset()
		for i, v := range values {
			if err := stmt.Bind(i+1, v); err != nil {
				return err
			}
		}
		if _, err := stmt.Step(); err != nil {
			return err
		}
	}
	if inTx {
		return db.Exec("COMMIT")
	}
	return nil
}

func quoteIdent(s string) string {
	out := make([]byte, 0, len(s)+2)
	out = append(out, '"')
	for i := 0; i < len(s); i++ {
		if s[i] == '"' {
			out = append(out, '"')
		}
		out = append(out, s[i])
	}
	out = append(out, '"')
	return string(out)
}
EOF
