// transformJSONLines decodes a stream of concatenated/newline separated JSON
// values and writes them in the rows format.
func transformJSONLines(path string, w io.Writer) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()
	dec := json.NewDecoder(bufio.NewReader(f))
	rw := newRowWriter(w)
	for {
		v, err := decodeJSONValue(dec)
		if err == io.EOF {
			break
		}
		if err != nil {
			return err
		}
		if err := rw.Write(v); err != nil {
			return err
		}
	}
	return rw.Close()
}

// transformText encodes the entire file as a single JSON string.
func transformText(path string, w io.Writer) error {
	b, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	enc, err := json.Marshal(string(b))
	if err != nil {
		return err
	}
	_, err = w.Write(enc)
	return err
}

// transformYAML decodes one or more YAML documents.
func transformYAML(path string, w io.Writer) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()
	dec := yaml.NewDecoder(f)
	var docs []interface{}
	for {
		var doc interface{}
		err := dec.Decode(&doc)
		if err == io.EOF {
			if len(docs) == 0 {
				return err
			}
			break
		}
		if err != nil {
			return err
		}
		docs = append(docs, doc)
	}
	if len(docs) == 1 {
		if err := checkYAMLKeys(docs[0]); err != nil {
			return err
		}
		enc := json.NewEncoder(w)
		return enc.Encode(docs[0])
	}
	rw := newRowWriter(w)
	for _, d := range docs {
		if err := checkYAMLKeys(d); err != nil {
			return err
		}
		b, err := json.Marshal(d)
		if err != nil {
			return err
		}
		if err := rw.WriteRaw(b); err != nil {
			return err
		}
	}
	return rw.Close()
}

// checkYAMLKeys reports maps with non-string keys, which cannot be
// represented in JSON.
func checkYAMLKeys(v interface{}) error {
	switch x := v.(type) {
	case map[string]interface{}:
		for _, e := range x {
			if err := checkYAMLKeys(e); err != nil {
				return err
			}
		}
	case map[interface{}]interface{}:
		return errors.New("json: unsupported type: interface {}")
	case []interface{}:
		for _, e := range x {
			if err := checkYAMLKeys(e); err != nil {
				return err
			}
		}
	}
	return nil
}

// logfmtError formats a decoding error in the logfmt style.
func logfmtError(pos, line int, msg string) error {
	return fmt.Errorf("logfmt syntax error at pos %d on line %d: %s", pos, line, msg)
}

// parseLogfmtLine decodes one logfmt record.
func parseLogfmtLine(line []byte, lineNo int) (*OMap, error) {
	row := NewOMap()
	n := len(line)
	pos := 0
	for {
		for pos < n && line[pos] <= ' ' {
			pos++
		}
		if pos >= n {
			break
		}
		c := line[pos]
		if c == '=' {
			return nil, logfmtError(pos+1, lineNo, "unexpected '='")
		}
		if c == '"' {
			return nil, logfmtError(pos+1, lineNo, "unexpected '\"'")
		}
		start := pos
		for pos < n && line[pos] > ' ' && line[pos] != '=' && line[pos] != '"' {
			pos++
		}
		key := line[start:pos]
		if !utf8.Valid(key) {
			return nil, logfmtError(pos+1, lineNo, "invalid key")
		}
		if pos < n && line[pos] == '"' {
			return nil, logfmtError(pos+1, lineNo, "unexpected '\"'")
		}
		if pos >= n || line[pos] <= ' ' {
			row.Set(string(key), "")
			continue
		}
		// line[pos] == '='
		pos++
		if pos >= n || line[pos] <= ' ' {
			row.Set(string(key), "")
			continue
		}
		switch line[pos] {
		case '=':
			return nil, logfmtError(pos+1, lineNo, "unexpected '='")
		case '"':
			// quoted value
			qstart := pos
			pos++
			escaped := false
			closed := false
			for pos < n {
				ch := line[pos]
				if escaped {
					escaped = false
				} else if ch == '\\' {
					escaped = true
				} else if ch == '"' {
					closed = true
					break
				}
				pos++
			}
			if !closed {
				return nil, logfmtError(n+1, lineNo, "unterminated quoted value")
			}
			pos++ // past closing quote
			val, ok := unquoteLogfmt(line[qstart:pos])
			if !ok {
				return nil, logfmtError(pos+1, lineNo, "invalid quoted value")
			}
			row.Set(string(key), val)
			if pos < n {
				if line[pos] == '=' {
					return nil, logfmtError(pos+1, lineNo, "unexpected '='")
				}
				if line[pos] == '"' {
					return nil, logfmtError(pos+1, lineNo, "unexpected '\"'")
				}
			}
		default:
			vstart := pos
			for pos < n && line[pos] > ' ' {
				if line[pos] == '=' {
					return nil, logfmtError(pos+1, lineNo, "unexpected '='")
				}
				if line[pos] == '"' {
					return nil, logfmtError(pos+1, lineNo, "unexpected '\"'")
				}
				pos++
			}
			row.Set(string(key), string(line[vstart:pos]))
		}
	}
	return row, nil
}

// unquoteLogfmt decodes a double-quoted logfmt value with JSON-like
// escapes. Returns false when the escapes are invalid.
func unquoteLogfmt(s []byte) (string, bool) {
	if len(s) < 2 || s[0] != '"' || s[len(s)-1] != '"' {
		return "", false
	}
	s = s[1 : len(s)-1]
	out := make([]byte, 0, len(s))
	for i := 0; i < len(s); {
		c := s[i]
		if c != '\\' {
			if c < utf8.RuneSelf {
				out = append(out, c)
				i++
				continue
			}
			r, size := utf8.DecodeRune(s[i:])
			if r == utf8.RuneError && size == 1 {
				out = append(out, []byte(string(utf8.RuneError))...)
				i++
				continue
			}
			out = append(out, s[i:i+size]...)
			i += size
			continue
		}
		i++
		if i >= len(s) {
			return "", false
		}
		switch s[i] {
		case '"', '\\', '/', '\'':
			out = append(out, s[i])
			i++
		case 'b':
			out = append(out, '\b')
			i++
		case 'f':
			out = append(out, '\f')
			i++
		case 'n':
			out = append(out, '\n')
			i++
		case 'r':
			out = append(out, '\r')
			i++
		case 't':
			out = append(out, '\t')
			i++
		case 'u':
			r, ok := hex4(s[i+1:])
			if !ok {
				return "", false
			}
			i += 5
			if utf16IsSurrogate(r) {
				if i+1 < len(s) && s[i] == '\\' && s[i+1] == 'u' {
					r2, ok2 := hex4(s[i+2:])
					if ok2 {
						if dec := utf16Decode(r, r2); dec != utf8.RuneError {
							i += 6
							out = utf8.AppendRune(out, dec)
							continue
						}
					}
				}
				r = utf8.RuneError
			}
			out = utf8.AppendRune(out, r)
		default:
			return "", false
		}
	}
	return string(out), true
}

func hex4(s []byte) (rune, bool) {
	if len(s) < 4 {
		return 0, false
	}
	var r rune
	for i := 0; i < 4; i++ {
		c := s[i]
		var v byte
		switch {
		case '0' <= c && c <= '9':
			v = c - '0'
		case 'a' <= c && c <= 'f':
			v = c - 'a' + 10
		case 'A' <= c && c <= 'F':
			v = c - 'A' + 10
		default:
			return 0, false
		}
		r = r*16 + rune(v)
	}
	return r, true
}

func utf16IsSurrogate(r rune) bool { return 0xd800 <= r && r < 0xe000 }

func utf16Decode(r1, r2 rune) rune {
	if 0xd800 <= r1 && r1 < 0xdc00 && 0xdc00 <= r2 && r2 < 0xe000 {
		return (r1-0xd800)<<10 | (r2 - 0xdc00) + 0x10000
	}
	return utf8.RuneError
}

