package main

import (
	"fmt"
	"io"
	"math"
	"regexp"
	"sort"
	"strings"

	"github.com/mattn/go-runewidth"
)

const wrapWidth = 30

var numericCellRe = regexp.MustCompile(`^-?(\d{1,3}(,\d{3})+|\d+)(\.\d+)?$`)

func isNumericCell(s string) bool {
	return numericCellRe.MatchString(strings.TrimSpace(s))
}

func displayWidth(s string) int {
	return runewidth.StringWidth(s)
}

// wrapWords breaks words into lines minimising raggedness. The final line
// carries no cost so earlier lines are filled as evenly as possible.
func wrapWords(words []string, lim int) []string {
	n := len(words)
	if n == 0 {
		return []string{""}
	}
	widths := make([]int, n)
	for i, w := range words {
		widths[i] = displayWidth(w)
	}
	// length[i][j]: width of words i..j joined with single spaces
	length := make([][]int, n)
	for i := 0; i < n; i++ {
		length[i] = make([]int, n)
		length[i][i] = widths[i]
		for j := i + 1; j < n; j++ {
			length[i][j] = length[i][j-1] + 1 + widths[j]
		}
	}
	const penalty = 100000
	cost := make([]int, n)
	nbrk := make([]int, n)
	for i := range cost {
		cost[i] = math.MaxInt32
	}
	for i := n - 1; i >= 0; i-- {
		if length[i][n-1] <= lim || i == n-1 {
			cost[i] = 0
			nbrk[i] = n
			continue
		}
		for j := i + 1; j < n; j++ {
			d := lim - length[i][j-1]
			c := d*d + cost[j]
			if length[i][j-1] > lim {
				c += penalty
			}
			if c < cost[i] {
				cost[i] = c
				nbrk[i] = j
			}
		}
	}
	var lines []string
	for i := 0; i < n; {
		lines = append(lines, strings.Join(words[i:nbrk[i]], " "))
		i = nbrk[i]
	}
	return lines
}

// cellLines splits a cell into display lines, wrapping long content.
func cellLines(s string) []string {
	lines := strings.Split(s, "\n")
	maxW := 0
	for _, l := range lines {
		if w := displayWidth(l); w > maxW {
			maxW = w
		}
	}
	if maxW <= wrapWidth {
		return lines
	}
	words := strings.Split(strings.Join(lines, " "), " ")
	lim := wrapWidth
	for _, w := range words {
		if ww := displayWidth(w); ww > lim {
			lim = ww
		}
	}
	return wrapWords(words, lim)
}

func padRight(s string, w int) string {
	gap := w - displayWidth(s)
	if gap <= 0 {
		return s
	}
	return s + strings.Repeat(" ", gap)
}

func padLeft(s string, w int) string {
	gap := w - displayWidth(s)
	if gap <= 0 {
		return s
	}
	return strings.Repeat(" ", gap) + s
}

func padCenter(s string, w int) string {
	gap := w - displayWidth(s)
	if gap <= 0 {
		return s
	}
	left := gap / 2
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", gap-left)
}

// renderTable draws an ASCII table with centred headers and per-cell
// alignment (numbers to the right, everything else to the left).
func renderTable(w io.Writer, headers []string, rows [][]string) {
	ncol := len(headers)
	widths := make([]int, ncol)
	for i, h := range headers {
		widths[i] = displayWidth(h)
	}
	cells := make([][][]string, len(rows))
	for r, row := range rows {
		cells[r] = make([][]string, ncol)
		for c := 0; c < ncol; c++ {
			var v string
			if c < len(row) {
				v = row[c]
			}
			lines := cellLines(v)
			cells[r][c] = lines
			for _, l := range lines {
				if lw := displayWidth(l); lw > widths[c] {
					widths[c] = lw
				}
			}
		}
	}
	var sb strings.Builder
	sep := "+"
	for _, cw := range widths {
		sep += strings.Repeat("-", cw+2) + "+"
	}
	sb.WriteString(sep + "\n")
	sb.WriteString("|")
	for i, h := range headers {
		sb.WriteString(" " + padCenter(h, widths[i]) + " |")
	}
	sb.WriteString("\n" + sep + "\n")
	for _, row := range cells {
		height := 1
		for _, lines := range row {
			if len(lines) > height {
				height = len(lines)
			}
		}
		for li := 0; li < height; li++ {
			sb.WriteString("|")
			for c := 0; c < ncol; c++ {
				var line string
				if li < len(row[c]) {
					line = row[c][li]
				}
				var out string
				if isNumericCell(line) {
					out = padLeft(line, widths[c])
				} else {
					out = padRight(line, widths[c])
				}
				sb.WriteString(" " + out + " |")
			}
			sb.WriteString("\n")
		}
	}
	sb.WriteString(sep + "\n")
	io.WriteString(w, sb.String())
}

// formatPrettyValue renders a decoded JSON value for table display.
func formatPrettyValue(v interface{}) string {
	switch x := v.(type) {
	case nil:
		return "null"
	case string:
		return x
	case bool:
		if x {
			return "true"
		}
		return "false"
	case float64:
		return fmt.Sprintf("%v", x)
	case int64:
		return fmt.Sprintf("%v", x)
	case *OMap, []interface{}, map[string]interface{}:
		b, err := encodeValue(toPlain(x))
		if err != nil {
			return fmt.Sprintf("%v", x)
		}
		return string(b)
	}
	return fmt.Sprintf("%v", v)
}

// prettyRows prints decoded rows (array of objects) as a table with the
// columns sorted by name and a row count footer.
func prettyRows(w io.Writer, rows []interface{}) {
	colSet := map[string]bool{}
	var objs []*OMap
	for _, r := range rows {
		m, ok := r.(*OMap)
		if !ok {
			continue
		}
		objs = append(objs, m)
		for _, k := range m.Keys {
			colSet[k] = true
		}
	}
	headers := make([]string, 0, len(colSet))
	for k := range colSet {
		headers = append(headers, k)
	}
	sort.Strings(headers)
	table := make([][]string, len(objs))
	for i, m := range objs {
		row := make([]string, len(headers))
		for j, h := range headers {
			v, ok := m.Get(h)
			if !ok {
				row[j] = "null"
			} else {
				row[j] = formatPrettyValue(v)
			}
		}
		table[i] = row
	}
	renderTable(w, headers, table)
	if len(objs) == 1 {
		fmt.Fprintf(w, "(1 row)\n")
	} else {
		fmt.Fprintf(w, "(%d rows)\n", len(objs))
	}
}

// prettyShape renders a shape in the indented "X of" format.
func prettyShape(s *Shape) string {
	lines := prettyShapeLines(s)
	return strings.Join(lines, "\n") + "\n"
}

func indentLines(lines []string, n int) []string {
	pad := strings.Repeat(" ", n)
	out := make([]string, len(lines))
	for i, l := range lines {
		out[i] = pad + l
	}
	return out
}

func prettyShapeLines(s *Shape) []string {
	switch s.Kind {
	case KindScalar:
		return []string{s.Scalar}
	case KindUnknown:
		return []string{"Unknown"}
	case KindArray:
		return append([]string{"Array of"}, indentLines(prettyShapeLines(s.Array), 2)...)
	case KindObject:
		lines := []string{"Object of"}
		keys := make([]string, len(s.Object.Keys))
		copy(keys, s.Object.Keys)
		sort.Strings(keys)
		for _, k := range keys {
			lines = append(lines, "  "+k+" of")
			lines = append(lines, indentLines(prettyShapeLines(s.Object.Fields[k]), 4)...)
		}
		return lines
	case KindVaried:
		lines := []string{"Varied of"}
		for i, v := range s.Varied {
			child := prettyShapeLines(v)
			if i < len(s.Varied)-1 {
				child[len(child)-1] += " or"
			}
			lines = append(lines, indentLines(child, 2)...)
		}
		return lines
	}
	return []string{"Unknown"}
}
