package main

import (
	"encoding/json"
	"sort"
	"strings"
)

type columnDef struct {
	Name string
	Path []string
	Type string
}

// sqlTypeForShape maps a field shape to a SQLite column type.
func sqlTypeForShape(s *Shape) string {
	switch s.Kind {
	case KindScalar:
		switch s.Scalar {
		case ScalarNumber:
			return "REAL"
		case ScalarBoolean:
			return "BOOLEAN"
		}
		return "TEXT"
	case KindVaried:
		if len(s.Varied) == 2 && s.Varied[1].Kind == KindScalar && s.Varied[1].Scalar == ScalarNull && s.Varied[0].Kind == KindScalar {
			return sqlTypeForShape(s.Varied[0])
		}
	}
	return "TEXT"
}

// flattenColumns derives table columns from an object shape, descending
// into nested objects with dotted names.
func flattenColumns(obj *ObjectShape, prefix []string, out *[]columnDef) {
	for _, k := range obj.Keys {
		s := obj.Fields[k]
		path := append(append([]string{}, prefix...), k)
		if s.Kind == KindObject {
			flattenColumns(s.Object, path, out)
			continue
		}
		*out = append(*out, columnDef{Name: strings.Join(path, "."), Path: path, Type: sqlTypeForShape(s)})
	}
}

func lookupPath(row *OMap, path []string) (interface{}, bool) {
	var cur interface{} = row
	for _, p := range path {
		m, ok := cur.(*OMap)
		if !ok {
			return nil, false
		}
		v, ok := m.Get(p)
		if !ok {
			return nil, false
		}
		cur = v
	}
	return cur, true
}

// bindValue converts a decoded JSON value into a SQLite bind value.
func bindValue(v interface{}) (interface{}, error) {
	switch x := v.(type) {
	case nil, bool, float64, string, int64:
		return x, nil
	case *OMap, []interface{}, map[string]interface{}:
		b, err := json.Marshal(toPlain(x))
		if err != nil {
			return nil, err
		}
		return b, nil
	}
	return v, nil
}

// importRows creates table from the element shape and inserts every row.
func importRows(db *DB, table string, rows []interface{}, elemShape *Shape) error {
	var cols []columnDef
	flattenColumns(elemShape.Object, nil, &cols)
	sort.Slice(cols, func(i, j int) bool { return cols[i].Name < cols[j].Name })

	if err := db.Exec("DROP TABLE IF EXISTS " + quoteIdent(table)); err != nil {
		return err
	}
	create := "CREATE TABLE " + quoteIdent(table) + " ("
	insert := "INSERT INTO " + quoteIdent(table) + " VALUES ("
	for i, c := range cols {
		if i > 0 {
			create += ", "
			insert += ", "
		}
		create += quoteIdent(c.Name) + " " + c.Type
		insert += "?"
	}
	create += ")"
	insert += ")"
	if err := db.Exec(create); err != nil {
		return err
	}
	if err := db.Exec("BEGIN"); err != nil {
		return err
	}
	stmt, err := db.Prepare(insert)
	if err != nil {
		db.Exec("ROLLBACK")
		return err
	}
	defer stmt.Finalize()
	for _, r := range rows {
		row, ok := r.(*OMap)
		if !ok {
			continue
		}
		stmt.Reset()
		for i, c := range cols {
			var bv interface{}
			if v, ok := lookupPath(row, c.Path); ok {
				bv, err = bindValue(v)
				if err != nil {
					db.Exec("ROLLBACK")
					return err
				}
			}
			if err := stmt.Bind(i+1, bv); err != nil {
				db.Exec("ROLLBACK")
				return err
			}
		}
		if _, err := stmt.Step(); err != nil {
			db.Exec("ROLLBACK")
			return err
		}
	}
	return db.Exec("COMMIT")
}
