package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"regexp"
	"strconv"
	"strings"
)

// tableRef is a reference to an input file (and optional path into it)
// found in a query.
type tableRef struct {
	Index int
	Path  string
}

var placeholderRe = regexp.MustCompile(`\{(\d+)?(?:,\s*)?(?:"([^"]*)"|'([^']*)')?\}`)

// rewriteQuery replaces {N}, {N, "path"} and {} placeholders with table
// names and returns the references in order of appearance.
func rewriteQuery(query string, nfiles int, strict bool) (string, []tableRef) {
	var refs []tableRef
	out := placeholderRe.ReplaceAllStringFunc(query, func(m string) string {
		sub := placeholderRe.FindStringSubmatch(m)
		// Validate the exact grammar: {N}, {N,"p"}, {N, "p"}, {"p"}, {}
		if !validPlaceholder(m) {
			return m
		}
		idx := 0
		if sub[1] != "" {
			n, err := strconv.Atoi(sub[1])
			if err != nil {
				return m
			}
			idx = n
		}
		path := sub[2]
		if path == "" {
			path = sub[3]
		}
		if idx >= nfiles {
			if strict {
				var files []FileInput
				_ = files[idx] // mirrors the original out-of-range failure
			}
			return ""
		}
		refs = append(refs, tableRef{Index: idx, Path: path})
		return "t_" + strconv.Itoa(idx)
	})
	return out, refs
}

func validPlaceholder(m string) bool {
	body := m[1 : len(m)-1]
	if body == "" {
		return true
	}
	i := 0
	for i < len(body) && body[i] >= '0' && body[i] <= '9' {
		i++
	}
	hasNum := i > 0
	rest := body[i:]
	if rest == "" {
		return hasNum
	}
	if hasNum {
		if rest[0] != ',' {
			return false
		}
		rest = strings.TrimLeft(rest[1:], " \t\n\r\f\v")
	}
	if len(rest) < 2 {
		return false
	}
	q := rest[0]
	if (q != '"' && q != '\'') || rest[len(rest)-1] != q {
		return false
	}
	return !strings.ContainsRune(rest[1:len(rest)-1], rune(q))
}

// runStatements executes all statements in query, returning the column
// names and rows of the final statement.
func runStatements(db *DB, query string) ([]string, [][]interface{}, error) {
	sql := query
	for {
		stmt, err := db.Prepare(sql)
		if err != nil {
			return nil, nil, err
		}
		if stmt.Empty() {
			// An empty statement with non-blank trailing text never
			// progresses; mirror the original by waiting indefinitely.
			if strings.TrimSpace(stmt.tail) == "" && strings.TrimSpace(sql) == "" {
				select {}
			}
			if strings.TrimSpace(sql) != "" {
				select {}
			}
			return nil, nil, nil
		}
		if strings.TrimSpace(stmt.tail) != "" {
			// Not the last statement: execute without collecting rows.
			for {
				more, err := stmt.Step()
				if err != nil {
					stmt.Finalize()
					return nil, nil, err
				}
				if !more {
					break
				}
			}
			stmt.Finalize()
			sql = stmt.tail
			continue
		}
		ncol := stmt.ColumnCount()
		cols := make([]string, ncol)
		for i := 0; i < ncol; i++ {
			cols[i] = stmt.ColumnName(i)
		}
		var rows [][]interface{}
		for {
			more, err := stmt.Step()
			if err != nil {
				stmt.Finalize()
				return nil, nil, err
			}
			if !more {
				break
			}
			row := make([]interface{}, ncol)
			for i := 0; i < ncol; i++ {
				row[i] = stmt.ColumnValue(i)
			}
			rows = append(rows, row)
		}
		stmt.Finalize()
		return cols, rows, nil
	}
}

// writeResultJSON streams query results in the rows JSON format.
func writeResultJSON(w io.Writer, cols []string, rows [][]interface{}) error {
	rw := newRowWriter(w)
	for _, row := range rows {
		m := NewOMap()
		for i, c := range cols {
			v := row[i]
			if b, ok := v.([]byte); ok {
				v = string(b)
			}
			m.Set(c, v)
		}
		if err := rw.Write(m); err != nil {
			return err
		}
	}
	return rw.Close()
}

// resultToJSON renders results to a byte slice.
func resultToJSON(cols []string, rows [][]interface{}) ([]byte, error) {
	var buf bytes.Buffer
	if err := writeResultJSON(&buf, cols, rows); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// dumpJSONFile prints JSON text either raw, as a table or as a schema.
func dumpJSONFile(w io.Writer, data []byte, pretty bool, schema bool) error {
	if schema {
		_, s, err := shapeFromJSON(data)
		if err != nil {
			return err
		}
		if pretty {
			_, err := io.WriteString(w, prettyShape(s))
			return err
		}
		_, err = io.WriteString(w, shapeToJSON(s)+"\n")
		return err
	}
	if pretty {
		v, err := parseJSON(bytes.NewReader(data))
		if err != nil {
			return err
		}
		arr, ok := v.([]interface{})
		if !ok || len(arr) == 0 {
			panicNilTable()
		}
		if _, isObj := arr[0].(*OMap); !isObj {
			panicNilTable()
		}
		prettyRows(w, arr)
		return nil
	}
	if _, err := w.Write(data); err != nil {
		return err
	}
	_, err := io.WriteString(w, "\n")
	return err
}

// panicNilTable reproduces the crash the original tool hits when asked
// to pretty print something that is not a non-empty array of objects.
func panicNilTable() {
	var table *struct{ rows []string }
	_ = table.rows
}

func marshalJSONValue(v interface{}) string {
	b, err := json.Marshal(v)
	if err != nil {
		return fmt.Sprintf("%v", v)
	}
	return string(b)
}
