type queryContext struct {
	db         *DB
	states     []*fileState
	cacheValid bool
	fastPath   bool
	opts       options
	imported   map[string]bool
}

// ensureImported loads the referenced tables into the database.
func (c *queryContext) ensureImported(refs []tableRef) error {
	if c.cacheValid || c.fastPath {
		return nil
	}
	if c.imported == nil {
		c.imported = map[string]bool{}
	}
	for _, ref := range refs {
		table := fmt.Sprintf("t_%d", ref.Index)
		st := c.states[ref.Index]
		if st.value == nil && st.shape == nil {
			data, err := transformFile(st.in, c.opts.convertNumbers)
			if err != nil {
				return err
			}
			st.data = data
			v, s, err := shapeFromJSON(data)
			if err != nil {
				return err
			}
			st.value = v
			st.shape = s
		}
		shape, err := shapeAtPath(st.shape, ref.Path)
		if err != nil {
			return err
		}
		if !isArrayOfObjects(shape) {
			return errorf("Input is not an array of objects: %s.", st.in.Path)
		}
		val, _ := valueAtPath(st.value, ref.Path)
		rows, _ := val.([]interface{})
		logVerbose("Creating table %s", table)
		if err := importRows(c.db, table, rows, shape.Array); err != nil {
			return err
		}
		c.imported[table] = true
	}
	return nil
}

func (c *queryContext) runQuery(query string, w io.Writer, pretty bool, schema bool) error {
	rewritten, refs := rewriteQuery(query, len(c.states), !c.fastPath)
	if err := c.ensureImported(refs); err != nil {
		return err
	}
	cols, rows, err := runStatements(c.db, rewritten)
	if err != nil {
		return err
	}
	data, err := resultToJSON(cols, rows)
	if err != nil {
		return err
	}
	out := bufio.NewWriterSize(w, 1<<16)
	defer out.Flush()
	return dumpJSONFile(out, data, pretty, schema)
}

func isTerminal(f *os.File) bool {
	var termios syscall.Termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)))
	return errno == 0
}

// repl reads queries from stdin until EOF, printing each result as a table.
func repl(ctx *queryContext) int {
	tty := isTerminal(os.Stdin)
	reader := bufio.NewReader(os.Stdin)
	for {
		if tty {
			fmt.Print("dsq> ")
		}
		line, err := reader.ReadString('\n')
		if err != nil {
			if err == io.EOF && line != "" {
				// process the final unterminated line
				if rc := replLine(ctx, line); rc != 0 {
					return rc
				}
			}
			fmt.Fprintln(os.Stderr, err.Error())
			return 1
		}
		if rc := replLine(ctx, line); rc != 0 {
			return rc
		}
	}
}

func replLine(ctx *queryContext, line string) int {
	line = strings.TrimRight(line, "\r\n")
	if strings.TrimSpace(line) == "" {
		return 0
	}
	var buf bytes.Buffer
	if err := ctx.runQuery(line, &buf, true, ctx.opts.schema); err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		return 1
	}
	os.Stdout.Write(buf.Bytes())
	return 0
}
