package main

import (
	"encoding/binary"
	"errors"
)

var errSnappyCorrupt = errors.New("snappy: corrupt input")

// snappyDecode decompresses a raw snappy block.
func snappyDecode(src []byte) ([]byte, error) {
	n, read := binary.Uvarint(src)
	if read <= 0 {
		return nil, errSnappyCorrupt
	}
	if n > 1<<32 {
		return nil, errors.New("snappy: decoded block is too large")
	}
	dst := make([]byte, n)
	s := read
	d := 0
	for s < len(src) {
		tag := src[s]
		s++
		var length, offset int
		switch tag & 3 {
		case 0: // literal
			length = int(tag>>2) + 1
			if length > 60 {
				extra := length - 60
				if s+extra > len(src) {
					return nil, errSnappyCorrupt
				}
				length = 0
				for i := 0; i < extra; i++ {
					length |= int(src[s+i]) << (8 * uint(i))
				}
				length++
				s += extra
			}
			if s+length > len(src) || d+length > len(dst) {
				return nil, errSnappyCorrupt
			}
			copy(dst[d:], src[s:s+length])
			s += length
			d += length
			continue
		case 1:
			if s >= len(src) {
				return nil, errSnappyCorrupt
			}
			length = 4 + int(tag>>2)&0x7
			offset = int(tag&0xe0)<<3 | int(src[s])
			s++
		case 2:
			if s+2 > len(src) {
				return nil, errSnappyCorrupt
			}
			length = 1 + int(tag>>2)
			offset = int(src[s]) | int(src[s+1])<<8
			s += 2
		case 3:
			if s+4 > len(src) {
				return nil, errSnappyCorrupt
			}
			length = 1 + int(tag>>2)
			offset = int(binary.LittleEndian.Uint32(src[s:]))
			s += 4
		}
		if offset <= 0 || d < offset || d+length > len(dst) {
			return nil, errSnappyCorrupt
		}
		// byte-by-byte copy to allow overlapping
		for i := 0; i < length; i++ {
			dst[d+i] = dst[d-offset+i]
		}
		d += length
	}
	if d != len(dst) {
		return nil, errSnappyCorrupt
	}
	return dst, nil
