package main

import (
	"encoding/binary"
	"errors"
	"math"
)

// Minimal Thrift compact protocol reader sufficient for parquet metadata.

type thriftReader struct {
	buf []byte
	pos int
}

var errThriftEOF = errors.New("thrift: unexpected end of data")

const (
	tBoolTrue  = 1
	tBoolFalse = 2
	tByte      = 3
	tI16       = 4
	tI32       = 5
	tI64       = 6
	tDouble    = 7
	tBinary    = 8
	tList      = 9
	tSet       = 10
	tMap       = 11
	tStruct    = 12
)

func (r *thriftReader) readByte() (byte, error) {
	if r.pos >= len(r.buf) {
		return 0, errThriftEOF
	}
	b := r.buf[r.pos]
	r.pos++
	return b, nil
}

func (r *thriftReader) readVarint() (uint64, error) {
	var x uint64
	var s uint
	for {
		b, err := r.readByte()
		if err != nil {
			return 0, err
		}
		x |= uint64(b&0x7f) << s
		if b < 0x80 {
			return x, nil
		}
		s += 7
		if s > 63 {
			return 0, errors.New("thrift: varint overflow")
		}
	}
}

func (r *thriftReader) readZigzag() (int64, error) {
	u, err := r.readVarint()
	if err != nil {
		return 0, err
	}
	return int64(u>>1) ^ -int64(u&1), nil
}

func (r *thriftReader) readBinary() ([]byte, error) {
	n, err := r.readVarint()
	if err != nil {
		return nil, err
	}
	if r.pos+int(n) > len(r.buf) {
		return nil, errThriftEOF
	}
	b := r.buf[r.pos : r.pos+int(n)]
	r.pos += int(n)
	return b, nil
}

// thriftValue is a decoded generic value.
type thriftStruct map[int16]interface{}

type thriftList struct {
	elemType byte
	items    []interface{}
}

func (r *thriftReader) readStruct() (thriftStruct, error) {
	out := thriftStruct{}
	var lastID int16
	for {
		hdr, err := r.readByte()
		if err != nil {
			return nil, err
		}
		if hdr == 0 {
			return out, nil
		}
		typ := hdr & 0x0f
		delta := int16(hdr >> 4)
		var id int16
		if delta != 0 {
			id = lastID + delta
		} else {
			z, err := r.readZigzag()
			if err != nil {
				return nil, err
			}
			id = int16(z)
		}
		lastID = id
		v, err := r.readValue(typ)
		if err != nil {
			return nil, err
		}
		out[id] = v
	}
}

func (r *thriftReader) readValue(typ byte) (interface{}, error) {
	switch typ {
	case tBoolTrue:
		return true, nil
	case tBoolFalse:
		return false, nil
	case tByte:
		b, err := r.readByte()
		return int64(int8(b)), err
	case tI16, tI32, tI64:
		return r.readZigzag()
	case tDouble:
		if r.pos+8 > len(r.buf) {
			return nil, errThriftEOF
		}
		v := math.Float64frombits(binary.LittleEndian.Uint64(r.buf[r.pos:]))
		r.pos += 8
		return v, nil
	case tBinary:
		return r.readBinary()
	case tList, tSet:
		hdr, err := r.readByte()
		if err != nil {
			return nil, err
		}
		n := int(hdr >> 4)
		et := hdr & 0x0f
		if n == 15 {
			nn, err := r.readVarint()
			if err != nil {
				return nil, err
			}
			n = int(nn)
		}
		l := &thriftList{elemType: et}
		for i := 0; i < n; i++ {
			v, err := r.readValue(et)
			if err != nil {
				return nil, err
			}
			l.items = append(l.items, v)
		}
		return l, nil
	case tMap:
		nn, err := r.readVarint()
		if err != nil {
			return nil, err
		}
		m := map[interface{}]interface{}{}
		if nn == 0 {
			return m, nil
		}
		kv, err := r.readByte()
		if err != nil {
			return nil, err
		}
		kt, vt := kv>>4, kv&0x0f
		for i := 0; i < int(nn); i++ {
			k, err := r.readValue(kt)
			if err != nil {
				return nil, err
			}
			v, err := r.readValue(vt)
			if err != nil {
				return nil, err
			}
			switch kk := k.(type) {
			case []byte:
				m[string(kk)] = v
			default:
				m[k] = v
			}
		}
		return m, nil
	case tStruct:
		return r.readStruct()
	}
	return nil, errors.New("thrift: unknown type")
}

// helpers for extracting fields
func (s thriftStruct) i64(id int16) int64 {
	if v, ok := s[id].(int64); ok {
		return v
	}
	return 0
}

func (s thriftStruct) has(id int16) bool {
	_, ok := s[id]
	return ok
}

func (s thriftStruct) str(id int16) string {
	if v, ok := s[id].([]byte); ok {
		return string(v)
	}
	return ""
}

func (s thriftStruct) list(id int16) []interface{} {
	if v, ok := s[id].(*thriftList); ok {
		return v.items
	}
	return nil
}

func (s thriftStruct) sub(id int16) thriftStruct {
	if v, ok := s[id].(thriftStruct); ok {
		return v
	}
	return nil
}

func (s thriftStruct) boolean(id int16, def bool) bool {
	if v, ok := s[id].(bool); ok {
		return v
	}
	return def
}
EOF
