// Parquet physical types
const (
	pqBoolean   = 0
	pqInt32     = 1
	pqInt64     = 2
	pqInt96     = 3
	pqFloat     = 4
	pqDouble    = 5
	pqByteArray = 6
	pqFixed     = 7
)

// Converted types of interest
const (
	pqConvUTF8 = 0
	pqConvMap  = 1
	pqConvList = 3
	pqConvEnum = 4
	pqConvJSON = 19
)

// Encodings
const (
	pqEncPlain           = 0
	pqEncPlainDictionary = 2
	pqEncRLE             = 3
	pqEncBitPacked       = 4
	pqEncDeltaBinary     = 5
	pqEncDeltaLength     = 6
	pqEncDeltaByteArray  = 7
	pqEncRLEDictionary   = 8
	pqEncByteStreamSplit = 9
)

type pqSchemaNode struct {
	Name          string
	Type          int
	TypeLength    int
	Repetition    int // 0 required, 1 optional, 2 repeated
	ConvertedType int
	HasConverted  bool
	HasType       bool
	Children      []*pqSchemaNode
	Parent        *pqSchemaNode
	DefLevel      int
	RepLevel      int
	Path          []string
	LeafIndex     int
	IsString      bool
}

func (n *pqSchemaNode) isLeaf() bool { return len(n.Children) == 0 }

type pqColumnChunk struct {
	meta      thriftStruct
	leaf      *pqSchemaNode
	codec     int
	numValues int64
	dataOff   int64
	dictOff   int64
	totalSize int64
}

type pqEntry struct {
	rep, def int
	val      interface{}
}

// pqMangleName converts a column name the way the reference tool exposes
// it: non alphanumeric bytes become their decimal code and names that do
// not begin with a letter are prefixed.
func pqMangleName(s string) string {
	if s == "" {
		return s
	}
	var out []byte
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' {
			out = append(out, c)
		} else {
			out = append(out, []byte(strconv.Itoa(int(c)))...)
		}
	}
	c := out[0]
	if c >= 'a' && c <= 'z' {
		out[0] = c - 'a' + 'A'
		return string(out)
	}
	if c >= 'A' && c <= 'Z' {
		return string(out)
	}
	return "PARGO_PREFIX_" + string(out)
}

type parquetFile struct {
	f        *os.File
	size     int64
	meta     thriftStruct
	root     *pqSchemaNode
	leaves   []*pqSchemaNode
	numRows  int64
	rowGroup []thriftStruct
}

func openParquet(path string) (*parquetFile, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	st, err := f.Stat()
	if err != nil {
		f.Close()
		return nil, err
	}
	size := st.Size()
	if size < 12 {
		f.Close()
		return nil, errors.New("file is too small to be a parquet file")
	}
	tail := make([]byte, 8)
	if _, err := f.ReadAt(tail, size-8); err != nil {
		f.Close()
		return nil, err
	}
	footerLen := int64(binary.LittleEndian.Uint32(tail[:4]))
	footerStart := size - 8 - footerLen
	if footerStart < 0 {
		f.Close()
		return nil, fmt.Errorf("seek %s: invalid argument", path)
	}
	if string(tail[4:]) != "PAR1" {
		f.Close()
		return nil, errors.New("invalid parquet file: bad magic number")
	}
	footer := make([]byte, footerLen)
	if _, err := f.ReadAt(footer, footerStart); err != nil {
		f.Close()
		return nil, err
	}
	tr := &thriftReader{buf: footer}
	meta, err := tr.readStruct()
	if err != nil {
		f.Close()
		return nil, err
	}
	pf := &parquetFile{f: f, size: size, meta: meta, numRows: meta.i64(3)}
	if err := pf.buildSchema(); err != nil {
		f.Close()
		return nil, err
	}
	for _, rg := range meta.list(4) {
		if s, ok := rg.(thriftStruct); ok {
			pf.rowGroup = append(pf.rowGroup, s)
		}
	}
	return pf, nil
}

func (pf *parquetFile) buildSchema() error {
	elems := pf.meta.list(2)
	if len(elems) == 0 {
		return errors.New("parquet: empty schema")
	}
	pos := 0
	var build func(parent *pqSchemaNode) (*pqSchemaNode, error)
	build = func(parent *pqSchemaNode) (*pqSchemaNode, error) {
		if pos >= len(elems) {
			return nil, errors.New("parquet: truncated schema")
		}
		se, _ := elems[pos].(thriftStruct)
		pos++
		n := &pqSchemaNode{Name: se.str(4), Parent: parent}
		if se.has(1) {
			n.HasType = true
			n.Type = int(se.i64(1))
		}
		n.TypeLength = int(se.i64(2))
		n.Repetition = int(se.i64(3))
		if se.has(6) {
			n.HasConverted = true
			n.ConvertedType = int(se.i64(6))
		}
		if lt := se.sub(10); lt != nil {
			// LogicalType union: 1 STRING, 2 MAP, 3 LIST, 4 ENUM, 5 DECIMAL ...
			if lt.has(1) || lt.has(4) || lt.has(13) {
				n.IsString = true
			}
			if lt.has(2) {
				n.HasConverted, n.ConvertedType = true, pqConvMap
			}
			if lt.has(3) {
				n.HasConverted, n.ConvertedType = true, pqConvList
			}
		}
		if n.HasConverted && (n.ConvertedType == pqConvUTF8 || n.ConvertedType == pqConvEnum || n.ConvertedType == pqConvJSON) {
			n.IsString = true
		}
		if parent != nil {
			n.DefLevel = parent.DefLevel
			n.RepLevel = parent.RepLevel
			if n.Repetition != 0 {
				n.DefLevel++
			}
			if n.Repetition == 2 {
				n.RepLevel++
			}
			n.Path = append(append([]string{}, parent.Path...), n.Name)
		}
		nchildren := int(se.i64(5))
		for i := 0; i < nchildren; i++ {
			c, err := build(n)
			if err != nil {
				return nil, err
			}
			n.Children = append(n.Children, c)
		}
		if nchildren == 0 && parent != nil {
			n.LeafIndex = len(pf.leaves)
			pf.leaves = append(pf.leaves, n)
		}
		return n, nil
	}
	root, err := build(nil)
	if err != nil {
		return err
	}
	pf.root = root
	return nil
}

func (pf *parquetFile) findLeaf(path []string) *pqSchemaNode {
	for _, l := range pf.leaves {
		if len(l.Path) != len(path) {
			continue
		}
		match := true
		for i := range path {
			if l.Path[i] != path[i] {
				match = false
				break
			}
		}
		if match {
			return l
		}
	}
	return nil
}

func pqDecompress(codec int, data []byte, uncompressedSize int) ([]byte, error) {
	switch codec {
	case 0:
		return data, nil
	case 1:
		return snappyDecode(data)
	case 2:
		zr, err := gzip.NewReader(bytes.NewReader(data))
		if err != nil {
			return nil, err
		}
		defer zr.Close()
		return io.ReadAll(zr)
	}
	return nil, fmt.Errorf("unsupported compression codec: %d", codec)
}

// bitReader reads little-endian bit-packed values.
type bitReader struct {
	buf  []byte
	pos  int // byte position
	bit  uint
	bits uint64
	nb   uint
}

func (b *bitReader) read(width uint) (uint64, bool) {
	for b.nb < width {
		if b.pos >= len(b.buf) {
			return 0, false
		}
		b.bits |= uint64(b.buf[b.pos]) << b.nb
		b.pos++
		b.nb += 8
	}
	v := b.bits & ((1 << width) - 1)
	b.bits >>= width
	b.nb -= width
	return v, true
}

func bitWidthFor(max int) uint {
	w := uint(0)
	for (1 << w) <= max {
		w++
	}
	return w
}

// decodeHybrid decodes count values in RLE/bit-packed hybrid encoding.
func decodeHybrid(data []byte, width uint, count int) ([]int, int, error) {
	out := make([]int, 0, count)
	pos := 0
	for len(out) < count {
		if pos >= len(data) {
			break
		}
		hdr, n := binary.Uvarint(data[pos:])
		if n <= 0 {
			return nil, pos, errors.New("parquet: bad hybrid header")
		}
		pos += n
		if hdr&1 == 0 {
			run := int(hdr >> 1)
			nbytes := int((width + 7) / 8)
			if pos+nbytes > len(data) {
				return nil, pos, errors.New("parquet: truncated rle run")
			}
			var v uint64
			for i := 0; i < nbytes; i++ {
				v |= uint64(data[pos+i]) << (8 * uint(i))
			}
			pos += nbytes
			for i := 0; i < run && len(out) < count; i++ {
				out = append(out, int(v))
			}
		} else {
			groups := int(hdr >> 1)
			nbytes := groups * int(width)
			if pos+nbytes > len(data) {
				return nil, pos, errors.New("parquet: truncated bit-packed run")
			}
			br := &bitReader{buf: data[pos : pos+nbytes]}
			for i := 0; i < groups*8 && len(out) < count; i++ {
				v, ok := br.read(width)
				if !ok {
					break
				}
				out = append(out, int(v))
			}
			pos += nbytes
		}
	}
	for len(out) < count {
		out = append(out, 0)
	}
	return out, pos, nil
}

// pqValueDecoder decodes PLAIN encoded values of a physical type.
func pqDecodePlain(data []byte, typ int, typeLen int, count int, leaf *pqSchemaNode) ([]interface{}, error) {
	out := make([]interface{}, 0, count)
	pos := 0
	switch typ {
	case pqBoolean:
		br := &bitReader{buf: data}
		for i := 0; i < count; i++ {
			v, ok := br.read(1)
			if !ok {
				return nil, errors.New("parquet: truncated boolean data")
			}
			out = append(out, v == 1)
		}
	case pqInt32:
		for i := 0; i < count; i++ {
			if pos+4 > len(data) {
				return nil, errors.New("parquet: truncated int32 data")
			}
			out = append(out, int64(int32(binary.LittleEndian.Uint32(data[pos:]))))
			pos += 4
		}
	case pqInt64:
		for i := 0; i < count; i++ {
			if pos+8 > len(data) {
				return nil, errors.New("parquet: truncated int64 data")
			}
			out = append(out, int64(binary.LittleEndian.Uint64(data[pos:])))
			pos += 8
		}
	case pqInt96:
		for i := 0; i < count; i++ {
			if pos+12 > len(data) {
				return nil, errors.New("parquet: truncated int96 data")
			}
			out = append(out, string(data[pos:pos+12]))
			pos += 12
		}
	case pqFloat:
		for i := 0; i < count; i++ {
			if pos+4 > len(data) {
				return nil, errors.New("parquet: truncated float data")
			}
			out = append(out, math.Float32frombits(binary.LittleEndian.Uint32(data[pos:])))
			pos += 4
		}
	case pqDouble:
		for i := 0; i < count; i++ {
			if pos+8 > len(data) {
				return nil, errors.New("parquet: truncated double data")
			}
			out = append(out, math.Float64frombits(binary.LittleEndian.Uint64(data[pos:])))
			pos += 8
		}
	case pqByteArray:
		for i := 0; i < count; i++ {
			if pos+4 > len(data) {
				return nil, errors.New("parquet: truncated byte array data")
			}
			n := int(binary.LittleEndian.Uint32(data[pos:]))
			pos += 4
			if pos+n > len(data) {
				return nil, errors.New("parquet: truncated byte array data")
			}
			out = append(out, string(data[pos:pos+n]))
			pos += n
		}
	case pqFixed:
		for i := 0; i < count; i++ {
			if pos+typeLen > len(data) {
				return nil, errors.New("parquet: truncated fixed data")
			}
			out = append(out, string(data[pos:pos+typeLen]))
			pos += typeLen
		}
	default:
		return nil, fmt.Errorf("parquet: unsupported type %d", typ)
	}
	return out, nil
}

// decodeDeltaBinaryPacked decodes DELTA_BINARY_PACKED int32/int64 values.
func decodeDeltaBinaryPacked(data []byte) ([]int64, int, error) {
	pos := 0
	readUvarint := func() (uint64, error) {
		v, n := binary.Uvarint(data[pos:])
		if n <= 0 {
			return 0, errors.New("parquet: bad delta header")
		}
		pos += n
		return v, nil
	}
	readZigzag := func() (int64, error) {
		u, err := readUvarint()
		if err != nil {
			return 0, err
		}
		return int64(u>>1) ^ -int64(u&1), nil
	}
	blockSize, err := readUvarint()
	if err != nil {
		return nil, 0, err
	}
	miniblocks, err := readUvarint()
	if err != nil {
		return nil, 0, err
	}
	total, err := readUvarint()
	if err != nil {
		return nil, 0, err
	}
	first, err := readZigzag()
	if err != nil {
		return nil, 0, err
	}
	out := make([]int64, 0, total)
	if total == 0 {
		return out, pos, nil
	}
	out = append(out, first)
	if miniblocks == 0 {
		return nil, 0, errors.New("parquet: bad delta miniblock count")
	}
	perMini := int(blockSize / miniblocks)
	cur := first
	for uint64(len(out)) < total {
		minDelta, err := readZigzag()
		if err != nil {
			return nil, 0, err
		}
		if pos+int(miniblocks) > len(data) {
			return nil, 0, errors.New("parquet: truncated delta block")
		}
		widths := data[pos : pos+int(miniblocks)]
		pos += int(miniblocks)
		for m := 0; m < int(miniblocks); m++ {
			if uint64(len(out)) >= total {
				break
			}
			w := uint(widths[m])
			nbytes := perMini * int(w) / 8
			if pos+nbytes > len(data) {
				return nil, 0, errors.New("parquet: truncated delta miniblock")
			}
			br := &bitReader{buf: data[pos : pos+nbytes]}
			for i := 0; i < perMini; i++ {
				var d uint64
				if w > 0 {
					d, _ = br.read(w)
				}
				if uint64(len(out)) >= total {
					continue
				}
				cur += minDelta + int64(d)
				out = append(out, cur)
			}
			pos += nbytes
		}
	}
	return out, pos, nil
}

func decodeDeltaLengthByteArray(data []byte) ([]interface{}, error) {
	lengths, pos, err := decodeDeltaBinaryPacked(data)
	if err != nil {
		return nil, err
	}
	out := make([]interface{}, 0, len(lengths))
	for _, l := range lengths {
		if pos+int(l) > len(data) {
			return nil, errors.New("parquet: truncated delta length data")
		}
		out = append(out, string(data[pos:pos+int(l)]))
		pos += int(l)
	}
	return out, nil
}

func decodeDeltaByteArray(data []byte) ([]interface{}, error) {
	prefixes, pos, err := decodeDeltaBinaryPacked(data)
	if err != nil {
		return nil, err
	}
	suffixes, err := decodeDeltaLengthByteArray(data[pos:])
	if err != nil {
		return nil, err
	}
	out := make([]interface{}, 0, len(prefixes))
	prev := ""
	for i, p := range prefixes {
		if i >= len(suffixes) {
			break
		}
		if int(p) > len(prev) {
			return nil, errors.New("parquet: bad delta prefix")
		}
		s := prev[:p] + suffixes[i].(string)
		out = append(out, s)
		prev = s
	}
	return out, nil
}

func decodeByteStreamSplit(data []byte, typ int, count int) ([]interface{}, error) {
	width := 4
	if typ == pqDouble {
		width = 8
	}
	if len(data) < width*count {
		return nil, errors.New("parquet: truncated byte stream split data")
	}
	out := make([]interface{}, 0, count)
	tmp := make([]byte, width)
	for i := 0; i < count; i++ {
		for b := 0; b < width; b++ {
			tmp[b] = data[b*count+i]
		}
		if width == 4 {
			out = append(out, math.Float32frombits(binary.LittleEndian.Uint32(tmp)))
		} else {
			out = append(out, math.Float64frombits(binary.LittleEndian.Uint64(tmp)))
		}
	}
	return out, nil
}

// readColumnChunk decodes all pages of a column chunk into entries.
func (pf *parquetFile) readColumnChunk(cc thriftStruct) ([]pqEntry, error) {
	md := cc.sub(3)
	if md == nil {
		return nil, errors.New("parquet: missing column metadata")
	}
	var path []string
	for _, p := range md.list(3) {
		if b, ok := p.([]byte); ok {
			path = append(path, string(b))
		}
	}
	leaf := pf.findLeaf(path)
	if leaf == nil {
		return nil, fmt.Errorf("parquet: unknown column %v", path)
	}
	codec := int(md.i64(4))
	numValues := md.i64(5)
	totalSize := md.i64(7)
	start := md.i64(9)
	if md.has(11) && md.i64(11) > 0 && md.i64(11) < start {
		start = md.i64(11)
	}
	if start+totalSize > pf.size {
		return nil, errors.New("parquet: column chunk out of bounds")
	}
	buf := make([]byte, totalSize)
	if _, err := pf.f.ReadAt(buf, start); err != nil {
		return nil, err
	}
	var dict []interface{}
	entries := make([]pqEntry, 0, numValues)
	pos := 0
	maxDef, maxRep := leaf.DefLevel, leaf.RepLevel
	for int64(len(entries)) < numValues && pos < len(buf) {
		tr := &thriftReader{buf: buf[pos:]}
		hdr, err := tr.readStruct()
		if err != nil {
			return nil, err
		}
		pos += tr.pos
		pageType := int(hdr.i64(1))
		uncompSize := int(hdr.i64(2))
		compSize := int(hdr.i64(3))
		if pos+compSize > len(buf) {
			return nil, errors.New("parquet: truncated page")
		}
		raw := buf[pos : pos+compSize]
		pos += compSize
		switch pageType {
		case 2: // dictionary page
			dph := hdr.sub(7)
			data, err := pqDecompress(codec, raw, uncompSize)
			if err != nil {
				return nil, err
			}
			n := int(dph.i64(1))
			dict, err = pqDecodePlain(data, leaf.Type, leaf.TypeLength, n, leaf)
			if err != nil {
				return nil, err
			}
		case 0: // data page v1
			dph := hdr.sub(5)
			n := int(dph.i64(1))
			enc := int(dph.i64(2))
			defEnc := int(dph.i64(3))
			repEnc := int(dph.i64(4))
			data, err := pqDecompress(codec, raw, uncompSize)
			if err != nil {
				return nil, err
			}
			p := 0
			var reps, defs []int
			if maxRep > 0 {
				reps, p, err = readLevelsV1(data, p, repEnc, bitWidthFor(maxRep), n)
				if err != nil {
					return nil, err
				}
			}
			if maxDef > 0 {
				defs, p, err = readLevelsV1(data, p, defEnc, bitWidthFor(maxDef), n)
				if err != nil {
					return nil, err
				}
			}
			nonNull := n
			if maxDef > 0 {
				nonNull = 0
				for _, d := range defs {
					if d == maxDef {
						nonNull++
					}
				}
			}
			vals, err := pqDecodeValues(data[p:], enc, leaf, nonNull, dict)
			if err != nil {
				return nil, err
			}
			entries = appendEntries(entries, reps, defs, vals, n, maxDef)
		case 3: // data page v2
			dph := hdr.sub(8)
			n := int(dph.i64(1))
			enc := int(dph.i64(4))
			defLen := int(dph.i64(5))
			repLen := int(dph.i64(6))
			compressed := dph.boolean(7, true)
			if repLen+defLen > len(raw) {
				return nil, errors.New("parquet: truncated page levels")
			}
			var reps, defs []int
			var err error
			if maxRep > 0 {
				reps, _, err = decodeHybrid(raw[:repLen], bitWidthFor(maxRep), n)
				if err != nil {
					return nil, err
				}
			}
			if maxDef > 0 {
				defs, _, err = decodeHybrid(raw[repLen:repLen+defLen], bitWidthFor(maxDef), n)
				if err != nil {
					return nil, err
				}
			}
			valData := raw[repLen+defLen:]
			if compressed {
				valData, err = pqDecompress(codec, valData, uncompSize-repLen-defLen)
				if err != nil {
					return nil, err
				}
			}
			nonNull := n
			if maxDef > 0 {
				nonNull = 0
				for _, d := range defs {
					if d == maxDef {
						nonNull++
					}
				}
			}
			vals, err := pqDecodeValues(valData, enc, leaf, nonNull, dict)
			if err != nil {
				return nil, err
			}
			entries = appendEntries(entries, reps, defs, vals, n, maxDef)
		default:
			// index pages etc. are skipped
		}
	}
	return entries, nil
}

func readLevelsV1(data []byte, p int, enc int, width uint, n int) ([]int, int, error) {
	if width == 0 {
		return make([]int, n), p, nil
	}
	if enc == pqEncBitPacked {
		nbytes := (n*int(width) + 7) / 8
		if p+nbytes > len(data) {
			return nil, p, errors.New("parquet: truncated levels")
		}
		br := &bitReader{buf: data[p : p+nbytes]}
		out := make([]int, 0, n)
		for i := 0; i < n; i++ {
			v, _ := br.read(width)
			out = append(out, int(v))
		}
		return out, p + nbytes, nil
	}
	if p+4 > len(data) {
		return nil, p, errors.New("parquet: truncated levels")
	}
	l := int(binary.LittleEndian.Uint32(data[p:]))
	p += 4
	if p+l > len(data) {
		return nil, p, errors.New("parquet: truncated levels")
	}
	levels, _, err := decodeHybrid(data[p:p+l], width, n)
	if err != nil {
		return nil, p, err
	}
	return levels, p + l, nil
}

func pqDecodeValues(data []byte, enc int, leaf *pqSchemaNode, count int, dict []interface{}) ([]interface{}, error) {
	switch enc {
	case pqEncPlain:
		return pqDecodePlain(data, leaf.Type, leaf.TypeLength, count, leaf)
	case pqEncPlainDictionary, pqEncRLEDictionary:
		if count == 0 {
			return nil, nil
		}
		if len(data) < 1 {
			return nil, errors.New("parquet: truncated dictionary indices")
		}
		width := uint(data[0])
		idx, _, err := decodeHybrid(data[1:], width, count)
		if err != nil {
			return nil, err
		}
		out := make([]interface{}, 0, count)
		for _, i := range idx {
			if i < 0 || i >= len(dict) {
				return nil, errors.New("parquet: dictionary index out of range")
			}
			out = append(out, dict[i])
		}
		return out, nil
	case pqEncDeltaBinary:
		vals, _, err := decodeDeltaBinaryPacked(data)
		if err != nil {
			return nil, err
		}
		out := make([]interface{}, 0, len(vals))
		for _, v := range vals {
			out = append(out, v)
		}
		return out, nil
	case pqEncDeltaLength:
		return decodeDeltaLengthByteArray(data)
	case pqEncDeltaByteArray:
		return decodeDeltaByteArray(data)
	case pqEncByteStreamSplit:
		return decodeByteStreamSplit(data, leaf.Type, count)
	case pqEncRLE:
		if leaf.Type == pqBoolean {
			if len(data) < 4 {
				return nil, errors.New("parquet: truncated rle booleans")
			}
			l := int(binary.LittleEndian.Uint32(data))
			if 4+l > len(data) {
				return nil, errors.New("parquet: truncated rle booleans")
			}
			bits, _, err := decodeHybrid(data[4:4+l], 1, count)
			if err != nil {
				return nil, err
			}
			out := make([]interface{}, 0, count)
			for _, b := range bits {
				out = append(out, b == 1)
			}
			return out, nil
		}
	}
	return nil, fmt.Errorf("parquet: unsupported encoding %d", enc)
}

func appendEntries(entries []pqEntry, reps, defs []int, vals []interface{}, n int, maxDef int) []pqEntry {
	vi := 0
	for i := 0; i < n; i++ {
		e := pqEntry{}
		if reps != nil {
			e.rep = reps[i]
		}
		if defs != nil {
			e.def = defs[i]
		} else {
			e.def = maxDef
		}
		if e.def == maxDef {
			if vi < len(vals) {
				e.val = vals[vi]
			}
			vi++
		}
		entries = append(entries, e)
	}
	return entries
}

// convertLeafValue applies logical type conversions to a raw value.
func convertLeafValue(leaf *pqSchemaNode, v interface{}) interface{} {
	return v
}

// assembleValue builds the nested value for one column within a single
// parent instance from its entries.
func assembleValue(nodes []*pqSchemaNode, entries []pqEntry) interface{} {
	if len(entries) == 0 {
		return nil
	}
	node := nodes[0]
	if node.Repetition == 2 {
		if entries[0].def < node.DefLevel {
			return []interface{}{}
		}
		var elems []interface{}
		start := 0
		for i := 1; i <= len(entries); i++ {
			if i == len(entries) || entries[i].rep <= node.RepLevel {
				elems = append(elems, assembleInstance(nodes, entries[start:i]))
				start = i
			}
		}
		return elems
	}
	return assembleInstance(nodes, entries)
}

func assembleInstance(nodes []*pqSchemaNode, entries []pqEntry) interface{} {
	node := nodes[0]
	e0 := entries[0]
	if e0.def < node.DefLevel {
		return nil
	}
	if node.isLeaf() {
		return convertLeafValue(node, e0.val)
	}
	child := nodes[1]
	m := NewOMap()
	m.Set(child.Name, assembleValue(nodes[1:], entries))
	return m
}

// mergeAssembled merges the contribution of one column into the record.
func mergeAssembled(dst, src interface{}) interface{} {
	switch d := dst.(type) {
	case *OMap:
		s, ok := src.(*OMap)
		if !ok {
			return dst
		}
		for _, k := range s.Keys {
			if existing, ok := d.Get(k); ok {
				d.Vals[k] = mergeAssembled(existing, s.Vals[k])
			} else {
				d.Set(k, s.Vals[k])
			}
		}
		return d
	case []interface{}:
		s, ok := src.([]interface{})
		if !ok {
			return dst
		}
		for i := range d {
			if i < len(s) {
				d[i] = mergeAssembled(d[i], s[i])
			}
		}
		for i := len(d); i < len(s); i++ {
			d = append(d, s[i])
		}
		return d
	case nil:
		return src
	}
	return dst
}

// simplifyLogical collapses LIST and MAP group structures into plain JSON
// arrays and objects, and renames fields to their exported form.
func simplifyLogical(node *pqSchemaNode, v interface{}) interface{} {
	if v == nil {
		return nil
	}
	if node.Repetition == 2 {
		if arr, ok := v.([]interface{}); ok {
			out := make([]interface{}, len(arr))
			for i, e := range arr {
				out[i] = simplifyInstance(node, e)
			}
			return out
		}
	}
	return simplifyInstance(node, v)
}

func simplifyInstance(node *pqSchemaNode, v interface{}) interface{} {
	if node.isLeaf() || v == nil {
		return v
	}
	m, ok := v.(*OMap)
	if !ok {
		return v
	}
	if node.HasConverted && node.ConvertedType == pqConvList && len(node.Children) == 1 && node.Children[0].Repetition == 2 {
		rep := node.Children[0]
		inner, _ := m.Get(rep.Name)
		arr, _ := inner.([]interface{})
		out := make([]interface{}, 0, len(arr))
		for _, e := range arr {
			if len(rep.Children) == 1 {
				em, ok := e.(*OMap)
				if ok {
					ev, _ := em.Get(rep.Children[0].Name)
					out = append(out, simplifyLogical(rep.Children[0], ev))
					continue
				}
			}
			out = append(out, simplifyInstance(rep, e))
		}
		return out
	}
	if node.HasConverted && node.ConvertedType == pqConvMap && len(node.Children) == 1 && node.Children[0].Repetition == 2 && len(node.Children[0].Children) == 2 {
		rep := node.Children[0]
		inner, _ := m.Get(rep.Name)
		arr, _ := inner.([]interface{})
		out := NewOMap()
		for _, e := range arr {
			em, ok := e.(*OMap)
			if !ok {
				continue
			}
			k, _ := em.Get(rep.Children[0].Name)
			val, _ := em.Get(rep.Children[1].Name)
			out.Set(fmt.Sprintf("%v", k), simplifyLogical(rep.Children[1], val))
		}
		return out
	}
	out := NewOMap()
	for _, c := range node.Children {
		cv, ok := m.Get(c.Name)
		if !ok {
			continue
		}
		out.Set(pqMangleName(c.Name), simplifyLogical(c, cv))
	}
	return out
}

// readRows reads all rows in the file as ordered maps.
func (pf *parquetFile) readRows(emit func(*OMap) error) error {
	for _, rg := range pf.rowGroup {
		nrows := int(rg.i64(3))
		records := make([]*OMap, nrows)
		for i := range records {
			records[i] = NewOMap()
		}
		for _, ccv := range rg.list(1) {
			cc, ok := ccv.(thriftStruct)
			if !ok {
				continue
			}
			entries, err := pf.readColumnChunk(cc)
			if err != nil {
				return err
			}
			md := cc.sub(3)
			var path []string
			for _, p := range md.list(3) {
				if b, ok := p.([]byte); ok {
					path = append(path, string(b))
				}
			}
			leaf := pf.findLeaf(path)
			// nodes from the top-level field down to the leaf
			var nodes []*pqSchemaNode
			for n := leaf; n != nil && n.Parent != nil; n = n.Parent {
				nodes = append([]*pqSchemaNode{n}, nodes...)
			}
			// split entries into records (rep == 0 starts a record)
			rec := 0
			start := 0
			for i := 1; i <= len(entries); i++ {
				if i == len(entries) || entries[i].rep == 0 {
					if rec < nrows {
						v := assembleValue(nodes, entries[start:i])
						top := nodes[0]
						if existing, ok := records[rec].Get(top.Name); ok {
							records[rec].Vals[top.Name] = mergeAssembled(existing, v)
						} else {
							records[rec].Set(top.Name, v)
						}
					}
					rec++
					start = i
				}
			}
		}
		for _, r := range records {
			out := NewOMap()
			for _, c := range pf.root.Children {
				v, ok := r.Get(c.Name)
				if !ok {
					v = nil
				}
				out.Set(pqMangleName(c.Name), simplifyLogical(c, v))
			}
			if err := emit(out); err != nil {
				return err
			}
		}
	}
	return nil
}

// transformParquet converts a parquet file into the JSON rows format.
func transformParquet(path string, w io.Writer) error {
	pf, err := openParquet(path)
	if err != nil {
		return err
	}
	defer pf.f.Close()
	rw := newRowWriter(w)
	err = pf.readRows(func(row *OMap) error {
		return rw.Write(row)
	})
	if err != nil {
		return err
	}
	return rw.Close()
}
