func openZipFile(z *zip.ReadCloser, name string) ([]byte, error) {
	name = strings.TrimPrefix(name, "/")
	for _, f := range z.File {
		if f.Name == name {
			rc, err := f.Open()
			if err != nil {
				return nil, err
			}
			defer rc.Close()
			return io.ReadAll(rc)
		}
	}
	return nil, errors.New("zip: file not found: " + name)
}

// cellColumnIndex converts a cell reference like "C12" to a 0-based column.
func cellColumnIndex(ref string) int {
	col := 0
	for i := 0; i < len(ref); i++ {
		c := ref[i]
		if c >= 'A' && c <= 'Z' {
			col = col*26 + int(c-'A'+1)
		} else if c >= 'a' && c <= 'z' {
			col = col*26 + int(c-'a'+1)
		} else {
			break
		}
	}
	return col - 1
}

// builtInNumFmts lists the OOXML built-in number formats.
