	55: "上午/下午 h\"時\"mm\"分\"", 56: "上午/下午 h\"時\"mm\"分\"ss\"秒\"", 57: "yyyy\"年\"m\"月\"", 58: "m\"月\"d\"日\"",
}

// isDateFormat reports whether a number format code renders dates/times.
func isDateFormat(code string) bool {
	// strip quoted sections, escaped characters, brackets and padding tokens
	var sb strings.Builder
	inQuote := false
	for i := 0; i < len(code); i++ {
		c := code[i]
		switch {
		case inQuote:
			if c == '"' {
				inQuote = false
			}
		case c == '"':
			inQuote = true
		case c == '\\' || c == '_' || c == '*':
			i++
		case c == '[':
			j := strings.IndexByte(code[i:], ']')
			if j < 0 {
				return false
			}
			inner := strings.ToLower(code[i+1 : i+j])
			if inner == "h" || inner == "hh" || inner == "m" || inner == "mm" || inner == "s" || inner == "ss" {
				sb.WriteString(inner)
			}
			i += j
		default:
			sb.WriteByte(c)
		}
	}
	s := strings.ToLower(sb.String())
	if strings.ContainsAny(s, "0#?") {
		return false
	}
	return strings.ContainsAny(s, "ymdhs")
}

// excelSerialToTime converts an Excel 1900-system serial into components.
func excelSerialToTime(serial float64) (year, month, day, hour, min, sec int, weekday int) {
	days := math.Floor(serial)
	frac := serial - days
	// seconds, rounded
	totalSec := int(math.Round(frac * 86400))
	if totalSec >= 86400 {
		totalSec = 0
		days++
	}
	hour = totalSec / 3600
	min = (totalSec % 3600) / 60
	sec = totalSec % 60
	d := int(days)
	// Excel treats 1900 as a leap year; serial 60 == 1900-02-29
	if d < 61 {
		d++
	}
	// days since 1899-12-31 -> convert via Unix epoch (1970-01-01 == serial 25569)
	unixDays := d - 25569
	y, m, dd := civilFromDays(unixDays)
	weekday = int((unixDays%7 + 11) % 7) // 1970-01-01 was a Thursday (4)
	return y, m, dd, hour, min, sec, weekday
}

// civilFromDays converts days since 1970-01-01 to a civil date.
func civilFromDays(z int) (int, int, int) {
	z += 719468
	era := z / 146097
	if z < 0 && z%146097 != 0 {
		era = (z - 146096) / 146097
	}
	doe := z - era*146097
	yoe := (doe - doe/1460 + doe/36524 - doe/146096) / 365
	y := yoe + era*400
	doy := doe - (365*yoe + yoe/4 - yoe/100)
	mp := (5*doy + 2) / 153
	d := doy - (153*mp+2)/5 + 1
	m := mp + 3
	if m > 12 {
		m -= 12
	}
	if m <= 2 {
		y++
	}
	return y, m, d
}

var monthNames = []string{"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"}
var dayNames = []string{"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"}

// formatExcelDate renders a serial number with a date/time format code.
func formatExcelDate(serial float64, code string) string {
	year, month, day, hour, min, sec, wd := excelSerialToTime(serial)
	lower := strings.ToLower(code)
	hasAMPM := strings.Contains(lower, "am/pm") || strings.Contains(lower, "a/p")
	var sb strings.Builder
	inQuote := false
	n := len(code)
	for i := 0; i < n; {
		c := code[i]
		if inQuote {
			if c == '"' {
				inQuote = false
			} else {
				sb.WriteByte(c)
			}
			i++
			continue
		}
		switch c {
		case '"':
			inQuote = true
			i++
			continue
		case '\\':
			if i+1 < n {
				sb.WriteByte(code[i+1])
			}
			i += 2
			continue
		case '_', '*':
			i += 2
			continue
		case '[':
			j := strings.IndexByte(code[i:], ']')
			if j < 0 {
				i = n
				continue
			}
			inner := strings.ToLower(code[i+1 : i+j])
			switch inner {
			case "h", "hh":
				sb.WriteString(strconv.Itoa(int(math.Floor(serial))*24 + hour))
			case "m", "mm":
				sb.WriteString(strconv.Itoa((int(math.Floor(serial))*24+hour)*60 + min))
			case "s", "ss":
				sb.WriteString(strconv.Itoa(((int(math.Floor(serial))*24+hour)*60+min)*60 + sec))
			}
			i += j + 1
			continue
		case ';':
			// only the first section is used
			i = n
			continue
		}
		lc := lower[i]
		// AM/PM markers
		if strings.HasPrefix(lower[i:], "am/pm") {
			if hour >= 12 {
				sb.WriteString("PM")
			} else {
				sb.WriteString("AM")
			}
			i += 5
			continue
		}
		if strings.HasPrefix(lower[i:], "a/p") {
			if hour >= 12 {
				sb.WriteString("P")
			} else {
				sb.WriteString("A")
			}
			i += 3
			continue
		}
		if lc == 'y' || lc == 'm' || lc == 'd' || lc == 'h' || lc == 's' || lc == 'e' {
			j := i
			for j < n && strings.ToLower(string(code[j])) == string(lc) {
				j++
			}
			count := j - i
			switch lc {
			case 'y', 'e':
				if count <= 2 {
					sb.WriteString(pad2(year % 100))
				} else {
					sb.WriteString(strconv.Itoa(year))
				}
			case 'm':
				// minutes if adjacent to h or s tokens
				isMinute := false
				if prevTok := lastTokenChar(lower, i); prevTok == 'h' {
					isMinute = true
				} else if nextTok := nextTokenChar(lower, j); nextTok == 's' {
					isMinute = true
				}
				if isMinute {
					if count == 1 {
						sb.WriteString(strconv.Itoa(min))
					} else {
						sb.WriteString(pad2(min))
					}
				} else {
					switch {
					case count == 1:
						sb.WriteString(strconv.Itoa(month))
					case count == 2:
						sb.WriteString(pad2(month))
					case count == 3:
						sb.WriteString(monthNames[month-1][:3])
					case count == 4:
						sb.WriteString(monthNames[month-1])
					default:
						sb.WriteString(monthNames[month-1][:1])
					}
				}
			case 'd':
				switch {
				case count == 1:
					sb.WriteString(strconv.Itoa(day))
				case count == 2:
					sb.WriteString(pad2(day))
				case count == 3:
					sb.WriteString(dayNames[wd][:3])
				default:
					sb.WriteString(dayNames[wd])
				}
			case 'h':
				h := hour
				if hasAMPM {
					h = hour % 12
					if h == 0 {
						h = 12
					}
				}
				if count == 1 {
					sb.WriteString(strconv.Itoa(h))
				} else {
					sb.WriteString(pad2(h))
				}
			case 's':
				if count == 1 {
					sb.WriteString(strconv.Itoa(sec))
				} else {
					sb.WriteString(pad2(sec))
				}
			}
			i = j
			continue
		}
		sb.WriteByte(c)
		i++
	}
	return sb.String()
}

func lastTokenChar(lower string, i int) byte {
	for k := i - 1; k >= 0; k-- {
		c := lower[k]
		if c == 'h' || c == 's' || c == 'y' || c == 'd' || c == 'm' {
			return c
		}
		if c >= 'a' && c <= 'z' {
			return 0
		}
	}
	return 0
}

func nextTokenChar(lower string, j int) byte {
	for k := j; k < len(lower); k++ {
		c := lower[k]
		if c == 'h' || c == 's' || c == 'y' || c == 'd' || c == 'm' {
			return c
		}
		if c >= 'a' && c <= 'z' {
			return 0
		}
	}
	return 0
}

func pad2(v int) string {
	if v < 10 {
		return "0" + strconv.Itoa(v)
	}
	return strconv.Itoa(v)
}

// formatGeneralNumber renders a float the way a spreadsheet displays it
// under the General format.
func formatGeneralNumber(f float64) string {
	if math.IsInf(f, 0) || math.IsNaN(f) {
		return strconv.FormatFloat(f, 'G', -1, 64)
	}
	abs := math.Abs(f)
	if abs != 0 && (abs >= 1e15 || abs < 1e-9) {
		s := strconv.FormatFloat(f, 'E', -1, 64)
		return s
	}
	return strconv.FormatFloat(f, 'f', -1, 64)
}

// addThousands inserts thousands separators into an integer string.
func addThousands(s string) string {
	neg := strings.HasPrefix(s, "-")
	if neg {
		s = s[1:]
	}
	var out []byte
	for i := 0; i < len(s); i++ {
		if i > 0 && (len(s)-i)%3 == 0 {
			out = append(out, ',')
		}
		out = append(out, s[i])
	}
	if neg {
		return "-" + string(out)
	}
	return string(out)
}

// formatNumberCode applies a (builtin) numeric format code.
func formatNumberCode(f float64, code string) string {
	switch code {
	case "0":
		return strconv.FormatFloat(f, 'f', 0, 64)
	case "0.00":
		return strconv.FormatFloat(f, 'f', 2, 64)
	case "#,##0", "#,##0 ;(#,##0)", "#,##0 ;[Red](#,##0)":
		return addThousands(strconv.FormatFloat(f, 'f', 0, 64))
	case "#,##0.00", "#,##0.00;(#,##0.00)", "#,##0.00;[Red](#,##0.00)":
		s := strconv.FormatFloat(f, 'f', 2, 64)
		i := strings.IndexByte(s, '.')
		return addThousands(s[:i]) + s[i:]
	case "0%":
		return strconv.FormatFloat(f*100, 'f', 0, 64) + "%"
	case "0.00%":
		return strconv.FormatFloat(f*100, 'f', 2, 64) + "%"
	case "0.00E+00":
		s := strconv.FormatFloat(f, 'E', 2, 64)
		return fixExponent(s, 2)
	case "##0.0E+0":
		s := strconv.FormatFloat(f, 'E', 1, 64)
		return fixExponent(s, 1)
	}
	return formatGeneralNumber(f)
}

func fixExponent(s string, digits int) string {
	i := strings.IndexByte(s, 'E')
	if i < 0 {
		return s
	}
	mant, exp := s[:i], s[i+1:]
	sign := exp[0]
	num := strings.TrimLeft(exp[1:], "0")
	for len(num) < digits {
		num = "0" + num
	}
	return mant + "E" + string(sign) + num
}

type xlsxStyleInfo struct {
	numFmtByXf map[int]int
	customFmts map[int]string
}

// formatXLSXNumber formats a numeric cell according to its style.
func (si *xlsxStyleInfo) format(v string, style int) string {
	f, err := strconv.ParseFloat(strings.TrimSpace(v), 64)
	if err != nil {
		return v
	}
	numFmt := 0
	if id, ok := si.numFmtByXf[style]; ok {
		numFmt = id
	}
	code, builtin := builtInNumFmts[numFmt]
	if !builtin {
		if c, ok := si.customFmts[numFmt]; ok {
			code = c
		} else {
			code = "General"
		}
	}
	if numFmt == 49 {
		return v
	}
	if isDateFormat(code) {
		return formatExcelDate(f, code)
	}
	if builtin {
		return formatNumberCode(f, code)
	}
	return formatGeneralNumber(f)
}

func cellTextFromRuns(ts []string, rs []struct {
	T string `xml:"t"`
}) string {
	var sb strings.Builder
	for _, t := range ts {
		sb.WriteString(t)
	}
	for _, r := range rs {
		sb.WriteString(r.T)
	}
	return sb.String()
}

// transformXLSX converts an Excel workbook into JSON rows (or an object of
// sheets when the workbook has several).
func transformXLSX(path_ string, w io.Writer) error {
	z, err := zip.OpenReader(path_)
	if err != nil {
		if err == zip.ErrFormat {
			return errors.New("zip: not a valid zip file")
		}
		return err
	}
	defer z.Close()

	wbData, err := openZipFile(z, "xl/workbook.xml")
	if err != nil {
		return err
	}
	var wb xlsxWorkbook
	if err := xml.Unmarshal(wbData, &wb); err != nil {
		return err
	}
	relTargets := map[string]string{}
	if relData, err := openZipFile(z, "xl/_rels/workbook.xml.rels"); err == nil {
		var rels xlsxRels
		if err := xml.Unmarshal(relData, &rels); err == nil {
			for _, r := range rels.Rels {
				t := r.Target
				if strings.HasPrefix(t, "/") {
					t = strings.TrimPrefix(t, "/")
				} else {
					t = path.Join("xl", t)
				}
				relTargets[r.ID] = t
			}
		}
	}
	var sst []string
	if sstData, err := openZipFile(z, "xl/sharedStrings.xml"); err == nil {
		var s xlsxSST
		if err := xml.Unmarshal(sstData, &s); err != nil {
			return err
		}
		for _, si := range s.SI {
			sst = append(sst, cellTextFromRuns(si.T, si.R))
		}
	}
	styles := &xlsxStyleInfo{numFmtByXf: map[int]int{}, customFmts: map[int]string{}}
	if stData, err := openZipFile(z, "xl/styles.xml"); err == nil {
		var st xlsxStyles
		if err := xml.Unmarshal(stData, &st); err == nil {
			for _, nf := range st.NumFmts {
				styles.customFmts[nf.ID] = nf.Code
			}
			for i, xf := range st.CellXfs {
				if xf.NumFmtID != nil {
					styles.numFmtByXf[i] = *xf.NumFmtID
				}
			}
		}
	}

	var names []string
	var sheets [][][]string
	for i, sh := range wb.Sheets {
		target, ok := relTargets[sh.ID]
		if !ok {
			target = "xl/worksheets/sheet" + strconv.Itoa(i+1) + ".xml"
		}
		data, err := openZipFile(z, target)
		if err != nil {
			return err
		}
		rows, err := parseXLSXSheet(data, sst, styles)
		if err != nil {
			return err
		}
		names = append(names, sh.Name)
		sheets = append(sheets, rows)
	}
	return writeSheets(w, names, sheets)
}

func parseXLSXSheet(data []byte, sst []string, styles *xlsxStyleInfo) ([][]string, error) {
	dec := xml.NewDecoder(strings.NewReader(string(data)))
	var rows [][]string
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		se, ok := tok.(xml.StartElement)
		if !ok || se.Name.Local != "row" {
			continue
		}
		var row xlsxRow
		if err := dec.DecodeElement(&row, &se); err != nil {
			return nil, err
		}
		var cells []string
		col := 0
		for _, c := range row.C {
			if c.R != "" {
				if idx := cellColumnIndex(c.R); idx >= 0 {
					col = idx
				}
			}
			for len(cells) < col {
				cells = append(cells, "")
			}
			val := xlsxCellValue(c, sst, styles)
			if col < len(cells) {
				cells[col] = val
			} else {
				cells = append(cells, val)
			}
			col++
		}
		rows = append(rows, trimTrailingEmpty(cells))
	}
	return rows, nil
}

func xlsxCellValue(c xlsxCell, sst []string, styles *xlsxStyleInfo) string {
	switch c.T {
	case "s":
		idx, err := strconv.Atoi(strings.TrimSpace(c.V))
		if err != nil || idx < 0 || idx >= len(sst) {
			return ""
		}
		return sst[idx]
	case "str", "e", "d":
		return c.V
	case "inlineStr":
		return cellTextFromRuns(c.IS.T, c.IS.R)
	case "b":
		if strings.TrimSpace(c.V) == "1" {
			return "TRUE"
		}
		return "FALSE"
	}
	if c.V == "" {
		return ""
	}
	return styles.format(c.V, c.S)
}
