package main

import (
	"io"
)

// sheetToRows converts a grid of string cells (first row = header) into
// row objects, mirroring the CSV conversion rules.
func sheetRowsToObjects(rows [][]string, emit func(*OMap) error) error {
	if len(rows) == 0 {
		return nil
	}
	header := rows[0]
	for _, rec := range rows[1:] {
		row := NewOMap()
		for i := range rec {
			row.Set(csvHeaderName(header, i), rec[i])
		}
		for i := len(rec); i < len(header); i++ {
			row.Set(csvHeaderName(header, i), nil)
		}
		if err := emit(row); err != nil {
			return err
		}
	}
	return nil
}

// writeSheets writes a set of named sheets. A single sheet is written as a
// plain array, several sheets as an object keyed by sheet name.
func writeSheets(w io.Writer, names []string, sheets [][][]string) error {
	if len(sheets) == 1 {
		rw := newRowWriter(w)
		if err := sheetRowsToObjects(sheets[0], rw.Write); err != nil {
			return err
		}
		return rw.Close()
	}
	if _, err := io.WriteString(w, "{"); err != nil {
		return err
	}
	for i, name := range names {
		if i > 0 {
			if _, err := io.WriteString(w, ","); err != nil {
				return err
			}
		}
		kb, _ := encodeValue(name)
		if _, err := w.Write(kb); err != nil {
			return err
		}
		if _, err := io.WriteString(w, ": "); err != nil {
			return err
		}
		rw := newRowWriter(w)
		if err := sheetRowsToObjects(sheets[i], rw.Write); err != nil {
			return err
		}
		if err := rw.Close(); err != nil {
			return err
		}
	}
	_, err := io.WriteString(w, "}")
	return err
}

// trimTrailingEmpty removes empty cells from the end of a row.
func trimTrailingEmpty(row []string) []string {
	n := len(row)
