// cellColumnIndex converts a cell reference like "C12" to a 0-based column.
func cellColumnIndex(ref string) int {
	col := 0
	for i := 0; i < len(ref); i++ {
		c := ref[i]
		if c >= 'A' && c <= 'Z' {
			col = col*26 + int(c-'A'+1)
		} else if c >= 'a' && c <= 'z' {
			col = col*26 + int(c-'a'+1)
		} else {
			break
		}
	}
	return col - 1
}

