// transformODS converts an OpenDocument spreadsheet into JSON rows.
func transformODS(path string, w io.Writer) error {
	z, err := zip.OpenReader(path)
	if err != nil {
		if err == zip.ErrFormat {
			return wrapError(errors.New("zip: not a valid zip file"))
		}
		return wrapError(err)
	}
	defer z.Close()
	content, err := openZipFile(z, "content.xml")
	if err != nil {
		return wrapError(err)
	}
	names, sheets, err := parseODSContent(content)
	if err != nil {
		return wrapError(err)
	}
	return writeSheets(w, names, sheets)
}

func odsAttr(se xml.StartElement, local string) string {
	for _, a := range se.Attr {
		if a.Name.Local == local {
			return a.Value
		}
	}
	return ""
}

func odsRepeat(se xml.StartElement, local string) int {
	v := odsAttr(se, local)
	if v == "" {
		return 1
	}
	n, err := strconv.Atoi(v)
	if err != nil || n < 1 {
		return 1
	}
	return n
}

// parseODSContent walks content.xml extracting every table as a grid of
// strings.
func parseODSContent(data []byte) ([]string, [][][]string, error) {
	dec := xml.NewDecoder(strings.NewReader(string(data)))
	var names []string
	var sheets [][][]string
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, nil, err
		}
		se, ok := tok.(xml.StartElement)
		if !ok || se.Name.Local != "table" || se.Name.Space == "" && false {
			continue
		}
		if se.Name.Local != "table" {
			continue
		}
		name := odsAttr(se, "name")
		rows, err := parseODSTable(dec, se)
		if err != nil {
			return nil, nil, err
		}
		names = append(names, name)
		sheets = append(sheets, rows)
	}
	return names, sheets, nil
}

func parseODSTable(dec *xml.Decoder, start xml.StartElement) ([][]string, error) {
	var rows [][]string
	depth := 1
	for depth > 0 {
		tok, err := dec.Token()
		if err != nil {
			return nil, err
		}
		switch t := tok.(type) {
		case xml.StartElement:
			if t.Name.Local == "table-row" {
				row, err := parseODSRow(dec, t)
				if err != nil {
					return nil, err
				}
				rep := odsRepeat(t, "number-rows-repeated")
				if len(row) == 0 && rep > 1 {
					// large runs of empty rows are collapsed
					rep = 1
				}
				for i := 0; i < rep; i++ {
					rows = append(rows, row)
				}
				continue
			}
			depth++
		case xml.EndElement:
			depth--
		}
	}
	for len(rows) > 0 && len(rows[len(rows)-1]) == 0 {
		rows = rows[:len(rows)-1]
	}
	return rows, nil
}

func parseODSRow(dec *xml.Decoder, start xml.StartElement) ([]string, error) {
	var cells []string
	depth := 1
	for depth > 0 {
		tok, err := dec.Token()
		if err != nil {
			return nil, err
		}
		switch t := tok.(type) {
		case xml.StartElement:
			if t.Name.Local == "table-cell" || t.Name.Local == "covered-table-cell" {
				text, err := parseODSCell(dec, t)
				if err != nil {
					return nil, err
				}
				rep := odsRepeat(t, "number-columns-repeated")
				if text == "" && rep > 1000 {
					rep = 1
				}
				for i := 0; i < rep; i++ {
					cells = append(cells, text)
				}
				continue
			}
			depth++
		case xml.EndElement:
			depth--
		}
	}
	return trimTrailingEmpty(cells), nil
}

// parseODSCell collects the textual content of a cell: paragraphs joined
// by newlines, with <text:s> expanded to spaces.
func parseODSCell(dec *xml.Decoder, start xml.StartElement) (string, error) {
	var paras []string
	var cur strings.Builder
	inPara := false
	depth := 1
	for depth > 0 {
		tok, err := dec.Token()
		if err != nil {
			return "", err
		}
		switch t := tok.(type) {
		case xml.StartElement:
			depth++
			switch t.Name.Local {
			case "p":
				if inPara {
					paras = append(paras, cur.String())
					cur.Reset()
				}
				inPara = true
			case "s":
				n := odsRepeat(t, "c")
				cur.WriteString(strings.Repeat(" ", n))
			case "line-break":
				cur.WriteString("\n")
			}
		case xml.EndElement:
			depth--
			if t.Name.Local == "p" && inPara {
				paras = append(paras, cur.String())
				cur.Reset()
				inPara = false
			}
		case xml.CharData:
			if inPara {
				cur.Write(t)
			}
		}
	}
	return strings.Join(paras, "\n"), nil
}
