package main

import (
	"bufio"
	"bytes"
	"compress/flate"
	"encoding/binary"
	"encoding/json"
	"errors"
	"fmt"
	"hash/crc32"
	"io"
	"math"
	"math/big"
	"os"
	"strings"
	"time"
)

type avroSchema struct {
	Type        string
	Name        string // full name for named types
	LogicalType string
	Scale       int
	Precision   int
	Fields      []avroField
	Symbols     []string
	Items       *avroSchema
	Values      *avroSchema
	Branches    []*avroSchema
	Size        int
}

type avroField struct {
	Name   string
	Schema *avroSchema
}

type avroParser struct {
	named map[string]*avroSchema
}

func (p *avroParser) parse(v interface{}, namespace string) (*avroSchema, error) {
	switch x := v.(type) {
	case string:
		return p.resolveName(x, namespace)
	case []interface{}:
		u := &avroSchema{Type: "union"}
		for _, b := range x {
			bs, err := p.parse(b, namespace)
			if err != nil {
				return nil, err
			}
			u.Branches = append(u.Branches, bs)
		}
		return u, nil
	case map[string]interface{}:
		typ, _ := x["type"].(string)
		s := &avroSchema{Type: typ}
		if lt, ok := x["logicalType"].(string); ok {
			s.LogicalType = lt
		}
		if sc, ok := x["scale"].(float64); ok {
			s.Scale = int(sc)
		}
		if pr, ok := x["precision"].(float64); ok {
			s.Precision = int(pr)
		}
		switch typ {
		case "record", "enum", "fixed":
			name, _ := x["name"].(string)
			ns := namespace
			if n, ok := x["namespace"].(string); ok {
				ns = n
			}
			full := name
			if !strings.Contains(name, ".") && ns != "" {
				full = ns + "." + name
			}
			s.Name = full
			if idx := strings.LastIndex(full, "."); idx >= 0 {
				ns = full[:idx]
			}
			p.named[full] = s
			switch typ {
			case "record":
				fields, _ := x["fields"].([]interface{})
				for _, f := range fields {
					fm, _ := f.(map[string]interface{})
					fname, _ := fm["name"].(string)
					fs, err := p.parse(fm["type"], ns)
					if err != nil {
						return nil, err
					}
					s.Fields = append(s.Fields, avroField{Name: fname, Schema: fs})
				}
			case "enum":
				syms, _ := x["symbols"].([]interface{})
				for _, sy := range syms {
					s.Symbols = append(s.Symbols, fmt.Sprintf("%v", sy))
				}
			case "fixed":
				if sz, ok := x["size"].(float64); ok {
					s.Size = int(sz)
				}
			}
			return s, nil
		case "array":
			items, err := p.parse(x["items"], namespace)
			if err != nil {
				return nil, err
			}
			s.Items = items
			return s, nil
		case "map":
			vals, err := p.parse(x["values"], namespace)
			if err != nil {
				return nil, err
			}
			s.Values = vals
			return s, nil
		default:
			base, err := p.resolveName(typ, namespace)
			if err != nil {
				return nil, err
			}
			if s.LogicalType != "" {
				cp := *base
				cp.LogicalType = s.LogicalType
				cp.Scale = s.Scale
				cp.Precision = s.Precision
				return &cp, nil
			}
			return base, nil
		}
	}
	return nil, fmt.Errorf("avro: unsupported schema %v", v)
}

func (p *avroParser) resolveName(name string, namespace string) (*avroSchema, error) {
	switch name {
	case "null", "boolean", "int", "long", "float", "double", "bytes", "string":
		return &avroSchema{Type: name}, nil
	}
	if s, ok := p.named[name]; ok {
		return s, nil
	}
	if namespace != "" {
		if s, ok := p.named[namespace+"."+name]; ok {
			return s, nil
		}
	}
	return nil, fmt.Errorf("avro: unknown type %q", name)
}

// unionKey is the name used for a union branch in the native encoding.
func (s *avroSchema) unionKey() string {
	base := s.Type
	if s.Name != "" {
		base = s.Name
	}
	if s.LogicalType != "" {
		return base + "." + s.LogicalType
	}
	return base
}

type avroReader struct {
	buf []byte
	pos int
}

var errAvroEOF = errors.New("avro: unexpected end of data")

func (r *avroReader) readLong() (int64, error) {
	var x uint64
	var s uint
	for {
		if r.pos >= len(r.buf) {
			return 0, errAvroEOF
		}
		b := r.buf[r.pos]
		r.pos++
		x |= uint64(b&0x7f) << s
		if b < 0x80 {
			break
		}
		s += 7
		if s > 63 {
			return 0, errors.New("avro: varint overflow")
		}
	}
	return int64(x>>1) ^ -int64(x&1), nil
}

func (r *avroReader) readBytes() ([]byte, error) {
	n, err := r.readLong()
	if err != nil {
		return nil, err
	}
	if n < 0 || r.pos+int(n) > len(r.buf) {
		return nil, errAvroEOF
	}
	b := r.buf[r.pos : r.pos+int(n)]
	r.pos += int(n)
	return b, nil
}

func (r *avroReader) readFixed(n int) ([]byte, error) {
	if r.pos+n > len(r.buf) {
		return nil, errAvroEOF
	}
	b := r.buf[r.pos : r.pos+n]
	r.pos += n
	return b, nil
}

// avroTime wraps time values so they marshal like time.Time.
type avroTime struct{ t time.Time }

func (a avroTime) MarshalJSON() ([]byte, error) { return json.Marshal(a.t) }

func (r *avroReader) readValue(s *avroSchema) (interface{}, error) {
	switch s.Type {
	case "null":
		return nil, nil
	case "boolean":
		b, err := r.readFixed(1)
		if err != nil {
			return nil, err
		}
		return b[0] != 0, nil
	case "int":
		v, err := r.readLong()
		if err != nil {
			return nil, err
		}
		switch s.LogicalType {
		case "date":
			return avroTime{time.Unix(v*86400, 0).UTC()}, nil
		case "time-millis":
			return int64(time.Duration(v) * time.Millisecond), nil
		}
		return v, nil
	case "long":
		v, err := r.readLong()
		if err != nil {
			return nil, err
		}
		switch s.LogicalType {
		case "timestamp-millis":
			return avroTime{time.Unix(v/1000, (v%1000)*1e6).UTC()}, nil
		case "timestamp-micros":
			return avroTime{time.Unix(v/1e6, (v%1e6)*1e3).UTC()}, nil
		case "time-micros":
			return int64(time.Duration(v) * time.Microsecond), nil
		}
		return v, nil
	case "float":
		b, err := r.readFixed(4)
		if err != nil {
			return nil, err
		}
		return math.Float32frombits(binary.LittleEndian.Uint32(b)), nil
	case "double":
		b, err := r.readFixed(8)
		if err != nil {
			return nil, err
		}
		return math.Float64frombits(binary.LittleEndian.Uint64(b)), nil
	case "bytes":
		b, err := r.readBytes()
		if err != nil {
			return nil, err
		}
		if s.LogicalType == "decimal" {
			return avroDecimal(b, s.Scale), nil
		}
		return append([]byte{}, b...), nil
	case "string":
		b, err := r.readBytes()
		if err != nil {
			return nil, err
		}
		return string(b), nil
	case "fixed":
		b, err := r.readFixed(s.Size)
		if err != nil {
			return nil, err
		}
		if s.LogicalType == "decimal" {
			return avroDecimal(b, s.Scale), nil
		}
		return append([]byte{}, b...), nil
	case "enum":
		idx, err := r.readLong()
		if err != nil {
			return nil, err
		}
		if idx < 0 || int(idx) >= len(s.Symbols) {
			return nil, errors.New("avro: enum index out of range")
		}
		return s.Symbols[idx], nil
	case "record":
		m := NewOMap()
		for _, f := range s.Fields {
			v, err := r.readValue(f.Schema)
			if err != nil {
				return nil, err
			}
			m.Set(f.Name, v)
		}
		return m, nil
	case "array":
		out := []interface{}{}
		for {
			n, err := r.readLong()
			if err != nil {
				return nil, err
			}
			if n == 0 {
				break
			}
			if n < 0 {
				n = -n
				if _, err := r.readLong(); err != nil {
					return nil, err
				}
			}
			for i := int64(0); i < n; i++ {
				v, err := r.readValue(s.Items)
				if err != nil {
