			case "record":
				fields, _ := x["fields"].([]interface{})
				for _, f := range fields {
					fm, _ := f.(map[string]interface{})
					fname, _ := fm["name"].(string)
					fs, err := p.parse(fm["type"], ns)
					if err != nil {
						return nil, err
					}
					s.Fields = append(s.Fields, avroField{Name: fname, Schema: fs})
				}
			case "enum":
				syms, _ := x["symbols"].([]interface{})
				for _, sy := range syms {
					s.Symbols = append(s.Symbols, fmt.Sprintf("%v", sy))
				}
			case "fixed":
				if sz, ok := x["size"].(float64); ok {
					s.Size = int(sz)
				}
			}
			return s, nil
		case "array":
			items, err := p.parse(x["items"], namespace)
			if err != nil {
				return nil, err
			}
