var errAvroEOF = errors.New("avro: unexpected end of data")

func (r *avroReader) readLong() (int64, error) {
	var x uint64
	var s uint
	for {
		if r.pos >= len(r.buf) {
			return 0, errAvroEOF
		}
		b := r.buf[r.pos]
		r.pos++
		x |= uint64(b&0x7f) << s
		if b < 0x80 {
