	return sqlite3_bind_blob(stmt, idx, s, n, SQLITE_TRANSIENT);
}

// Evaluate "SELECT <fn>(?1, ?2, ...)" with the given argument values and
// hand the result back. Used to provide aliases for functions that newer
// SQLite releases ship natively (format(), unixepoch()).
static void forward_call(sqlite3_context *ctx, const char *fn, const char *prefix, const char *suffix, int argc, sqlite3_value **argv) {
	sqlite3 *db = sqlite3_context_db_handle(ctx);
	char sql[512];
	int n = snprintf(sql, sizeof(sql), "SELECT %s%s(", prefix, fn);
	int i;
	for (i = 0; i < argc && n < (int)sizeof(sql) - 16; i++) {
		n += snprintf(sql + n, sizeof(sql) - n, "%s?%d", i ? "," : "", i + 1);
	}
	snprintf(sql + n, sizeof(sql) - n, ")%s", suffix);
	sqlite3_stmt *stmt = NULL;
	if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
		sqlite3_result_error(ctx, sqlite3_errmsg(db), -1);
		return;
	}
	for (i = 0; i < argc; i++) {
		sqlite3_bind_value(stmt, i + 1, argv[i]);
	}
	int rc = sqlite3_step(stmt);
	if (rc == SQLITE_ROW) {
		sqlite3_result_value(ctx, sqlite3_column_value(stmt, 0));
	} else if (rc != SQLITE_DONE) {
		sqlite3_result_error(ctx, sqlite3_errmsg(db), -1);
	} else {
		sqlite3_result_null(ctx);
	}
	sqlite3_finalize(stmt);
